  add("calculus", "c2", 0, [{"type":"regular","q":"Use the definition of the derivative to find $f'(2)$ for $f(x) = 3x$.","answer":"3","solution":"Apply \\(\\lim_{h \\to 0}\\frac{f(2+h)-f(2)}{h} = \\lim_{h \\to 0}\\frac{3(2+h)-6}{h} = \\lim_{h \\to 0}\\frac{3h}{h} = 3\\)."},{"type":"regular","q":"What is the slope of the tangent line to \\(y = x^2 + 1\\) at $x = 1$?","answer":"2","solution":"The derivative is $f'(x) = 2x$, so $f'(1) = 2$."},{"type":"regular","q":"Find the equation of the tangent line to \\(f(x) = x^2\\) at the point $(1, 1)$.","answer":"$y = 2x - 1$","solution":"Slope at $x=1$ is $f'(1)=2$; use point-slope form: $y - 1 = 2(x - 1)$."},{"type":"regular","q":"Use the definition to compute $f'(0)$ for \\(f(x) = x^2 - 5x\\).","answer":"-5","solution":"Apply \\(\\lim_{h \\to 0}\\frac{(0+h)^2-5(0+h)-(0)}{h} = \\lim_{h \\to 0}\\frac{h^2-5h}{h} = \\lim_{h \\to 0}(h-5) = -5\\)."},{"type":"regular","q":"Find the tangent line to \\(y = 2x^2\\) at $(3, 18)$.","answer":"$y = 12x - 18$","solution":"Derivative is $f'(x) = 4x$, so $f'(3) = 12$; use point-slope form."},{"type":"regular","q":"What does the derivative $f'(a)$ represent geometrically?","answer":"The slope of the tangent line to the curve at $x = a$","solution":"The derivative is the instantaneous rate of change, which equals the slope of the tangent line."},{"type":"regular","q":"Use the definition to find $g'(1)$ for $g(x) = 4x + 2$.","answer":"4","solution":"Apply \\(\\lim_{h \\to 0}\\frac{4(1+h)+2-(4+2)}{h} = \\lim_{h \\to 0}\\frac{4h}{h} = 4\\)."},{"type":"regular","q":"Find the slope of the tangent to \\(y = x^3\\) at $x = 1$.","answer":"3","solution":"Use the definition: \\(\\lim_{h \\to 0}\\frac{(1+h)^3-1}{h} = 3\\)."},{"type":"word","q":"A ball is dropped from a height. Its position is \\(s(t) = 16t^2\\) feet after $t$ seconds. What is the instantaneous velocity at $t = 2$ seconds?","answer":"64 feet per second","solution":"The velocity is $s'(t) = 32t$, so $s'(2) = 64$."},{"type":"word","q":"The temperature of an oven is modeled by $T(t) = 100 + 5t$ degrees Fahrenheit at time $t$ minutes. What is the instantaneous rate of change of temperature at $t = 10$?","answer":"5 degrees per minute","solution":"The derivative $T'(t) = 5$ is constant, so the rate is 5 at any time."},{"type":"word","q":"A particle moves along a line with position \\(s(t) = t^2 + 3t\\). Find its instantaneous velocity at $t = 1$ second.","answer":"5 units per second","solution":"The velocity is $s'(t) = 2t + 3$, so $s'(1) = 5$."},{"type":"word","q":"Water flows into a tank at a rate modeled by \\(V(t) = 2t^2\\) liters after $t$ minutes. What is the instantaneous flow rate at $t = 3$ minutes?","answer":"12 liters per minute","solution":"The flow rate is $V'(t) = 4t$, so $V'(3) = 12$."},{"type":"word","q":"A car's position is \\(s(t) = 10t + t^2\\) meters. Find the tangent line to the position curve at $t = 2$ seconds.","answer":"$s = 14t - 4$","solution":"Velocity is $s'(t) = 10 + 2t$, so $s'(2) = 14$; at $t=2$, $s=24$, giving $s - 24 = 14(t - 2)$."},{"type":"word","q":"The revenue from selling $x$ items is $R(x) = 50x$ dollars. What is the instantaneous rate of change of revenue at $x = 100$?","answer":"50 dollars per item","solution":"The derivative $R'(x) = 50$ is constant."},{"type":"word","q":"A population grows according to $P(t) = 1000 + 50t$ individuals after $t$ years. What is the instantaneous growth rate at $t = 5$ years?","answer":"50 individuals per year","solution":"The growth rate is $P'(t) = 50$ at all times."}]);
  add("calculus", "c2", 1, [{"type":"regular","q":"\\(\\dfrac{d}{dx}(x^7)\\)?","answer":"\\(7x^6\\)","solution":"Apply the power rule: \\(\\dfrac{d}{dx}(x^n) = nx^{n-1}\\)."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(5x^3)\\)?","answer":"\\(15x^2\\)","solution":"Use the constant multiple rule and power rule: \\(5 \\cdot 3x^2 = 15x^2\\)."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(x^4 - 2x^2 + 6)\\)?","answer":"\\(4x^3 - 4x\\)","solution":"Differentiate term-by-term: \\(4x^3 - 4x + 0\\)."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(8x^2 - 3x + 9)\\)?","answer":"$16x - 3$","solution":"Apply the power rule and constant rule to each term."},{"type":"regular","q":"\\(\\dfrac{d}{dx}\\left(\\dfrac{1}{x}\\right)\\)?","answer":"\\(-\\dfrac{1}{x^2}\\)","solution":"Rewrite as \\(x^{-1}\\) and apply the power rule: \\(-x^{-2}\\)."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(x^{-3})\\)?","answer":"\\(-3x^{-4}\\)","solution":"Apply the power rule: \\(-3x^{-3-1} = -3x^{-4}\\)."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(7x^4 + 2x - 5)\\)?","answer":"\\(28x^3 + 2\\)","solution":"Differentiate each term using the power rule."},{"type":"regular","q":"\\(\\dfrac{d}{dx}\\left(x^{1/2}\\right)\\)?","answer":"\\(\\dfrac{1}{2}x^{-1/2}\\) or \\(\\dfrac{1}{2\\sqrt{x}}\\)","solution":"Apply the power rule: \\(\\dfrac{1}{2}x^{1/2-1} = \\dfrac{1}{2}x^{-1/2}\\)."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(9x^5 - 4x^3 + x)\\)?","answer":"\\(45x^4 - 12x^2 + 1\\)","solution":"Differentiate each term using the power rule."},{"type":"regular","q":"\\(\\dfrac{d}{dx}\\left(\\dfrac{1}{x^2}\\right)\\)?","answer":"\\(-2x^{-3}\\) or \\(-\\dfrac{2}{x^3}\\)","solution":"Rewrite as \\(x^{-2}\\) and apply the power rule."},{"type":"word","q":"The cost to produce $x$ units is \\(C(x) = 100 + 5x + 0.1x^2\\) dollars. Find the marginal cost at $x = 50$ units.","answer":"$5 + 10 = 15$ dollars per unit","solution":"The marginal cost is $C'(x) = 5 + 0.2x$, so $C'(50) = 5 + 10 = 15$."},{"type":"word","q":"The area of a square with side length $s$ is \\(A(s) = s^2\\). Find the rate of change of area with respect to side length at $s = 4$ cm.","answer":"8 cm per cm","solution":"The derivative is $A'(s) = 2s$, so $A'(4) = 8$."},{"type":"word","q":"The profit from selling $x$ items is \\(P(x) = 20x - x^2\\) dollars. Find the marginal profit at $x = 5$ items.","answer":"10 dollars per item","solution":"The marginal profit is $P'(x) = 20 - 2x$, so $P'(5) = 10$."},{"type":"word","q":"The volume of a sphere with radius $r$ is \\(V(r) = \\frac{4}{3}\\pi r^3\\). Find \\(\\dfrac{dV}{dr}\\) at $r = 2$ meters.","answer":"\\(16\\pi\\) cubic meters per meter","solution":"The derivative is \\(V'(r) = 4\\pi r^2\\), so \\(V'(2) = 16\\pi\\)."},{"type":"word","q":"The height of a plant is \\(h(t) = 2t^2 + 3t\\) cm after $t$ weeks. Find the growth rate at $t = 3$ weeks.","answer":"15 cm per week","solution":"The growth rate is $h'(t) = 4t + 3$, so $h'(3) = 15$."}]);
  add("calculus", "c2", 2, [{"type":"regular","q":"\\(\\dfrac{d}{dx}(\\tan x)\\)?","answer":"\\(\\sec^2 x\\)","solution":"The derivative of tangent is secant squared."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(\\sec x)\\)?","answer":"\\(\\sec x \\tan x\\)","solution":"Apply the standard derivative formula for secant."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(\\csc x)\\)?","answer":"\\(-\\csc x \\cot x\\)","solution":"Apply the standard derivative formula for cosecant."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(\\cot x)\\)?","answer":"\\(-\\csc^2 x\\)","solution":"The derivative of cotangent is negative cosecant squared."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(e^x + \\ln x)\\)?","answer":"\\(e^x + \\dfrac{1}{x}\\)","solution":"Differentiate each term: \\(\\dfrac{d}{dx}(e^x) = e^x\\) and \\(\\dfrac{d}{dx}(\\ln x) = \\dfrac{1}{x}\\)."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(3\\sin x - 2\\cos x)\\)?","answer":"\\(3\\cos x + 2\\sin x\\)","solution":"Differentiate: \\(3\\cos x - 2(-\\sin x) = 3\\cos x + 2\\sin x\\)."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(\\sin x + e^x)\\)?","answer":"\\(\\cos x + e^x\\)","solution":"Apply standard derivatives: \\(\\dfrac{d}{dx}(\\sin x) = \\cos x\\) and \\(\\dfrac{d}{dx}(e^x) = e^x\\)."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(5\\ln x - 4\\sin x)\\)?","answer":"\\(\\dfrac{5}{x} - 4\\cos x\\)","solution":"Differentiate each term using standard formulas."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(e^x + \\cos x - \\ln x)\\)?","answer":"\\(e^x - \\sin x - \\dfrac{1}{x}\\)","solution":"Apply standard derivatives to each term."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(2e^x + 3\\tan x)\\)?","answer":"\\(2e^x + 3\\sec^2 x\\)","solution":"Differentiate: \\(2e^x + 3\\sec^2 x\\)."},{"type":"word","q":"The position of a pendulum is \\(s(t) = \\sin t\\) meters. Find the velocity at \\(t = \\dfrac{\\pi}{4}\\) seconds.","answer":"\\(\\dfrac{\\sqrt{2}}{2}\\) meters per second","solution":"The velocity is \\(s'(t) = \\cos t\\), so \\(s'(\\pi/4) = \\cos(\\pi/4) = \\sqrt{2}/2\\)."},{"type":"word","q":"The temperature variation in a room is modeled by \\(T(t) = 20 + 5\\sin t\\) degrees Celsius. Find the rate of change at $t = 0$.","answer":"5 degrees per unit time","solution":"The rate is \\(T'(t) = 5\\cos t\\), so \\(T'(0) = 5\\cos(0) = 5\\)."},{"type":"word","q":"A bacterial population grows as \\(P(t) = 1000e^t\\) cells. Find the growth rate at $t = 1$ hour.","answer":"$1000e$ cells per hour","solution":"The growth rate is \\(P'(t) = 1000e^t\\), so $P'(1) = 1000e$."},{"type":"word","q":"The brightness of a light is \\(B(t) = 100\\cos t\\) lumens. Find the rate of change at \\(t = \\dfrac{\\pi}{2}\\).","answer":"$-100$ lumens per unit time","solution":"The rate is \\(B'(t) = -100\\sin t\\), so \\(B'(\\pi/2) = -100\\sin(\\pi/2) = -100\\)."},{"type":"word","q":"The amount of a radioactive substance is \\(A(t) = 500e^{-0.1t}\\) grams. Find the decay rate at $t = 10$ hours.","answer":"\\(-50e^{-1}\\) grams per hour","solution":"The decay rate is \\(A'(t) = 500(-0.1)e^{-0.1t} = -50e^{-0.1t}\\), so \\(A'(10) = -50e^{-1}\\)."}]);
  addCum("calculus", "c2", [{"type":"regular","q":"\\(\\dfrac{d}{dx}(x^6 - 3x^2 + 2)\\)?","answer":"\\(6x^5 - 6x\\)","solution":"Apply the power rule to each term."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(\\sin x + e^x + x^3)\\)?","answer":"\\(\\cos x + e^x + 3x^2\\)","solution":"Differentiate each term using standard formulas."},{"type":"regular","q":"Find the slope of the tangent to \\(y = x^4\\) at $x = 2$.","answer":"32","solution":"The derivative is \\(f'(x) = 4x^3\\), so $f'(2) = 32$."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(\\ln x + \\cos x)\\)?","answer":"\\(\\dfrac{1}{x} - \\sin x\\)","solution":"Apply standard derivatives: \\(\\dfrac{d}{dx}(\\ln x) = \\dfrac{1}{x}\\) and \\(\\dfrac{d}{dx}(\\cos x) = -\\sin x\\)."},{"type":"regular","q":"Find the equation of the tangent line to \\(y = e^x\\) at $(0, 1)$.","answer":"$y = x + 1$","solution":"The derivative is \\(f'(x) = e^x\\), so $f'(0) = 1$; use point-slope form."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(2\\tan x - 5x^2)\\)?","answer":"\\(2\\sec^2 x - 10x\\)","solution":"Differentiate each term using standard formulas."},{"type":"regular","q":"What is the slope of the tangent to \\(y = \\ln x\\) at $x = 1$?","answer":"1","solution":"The derivative is \\(f'(x) = \\dfrac{1}{x}\\), so $f'(1) = 1$."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(x^{-2} + 3e^x)\\)?","answer":"\\(-2x^{-3} + 3e^x\\)","solution":"Apply the power rule and exponential derivative."},{"type":"regular","q":"Find the tangent line to \\(y = \\sin x\\) at $x = 0$.","answer":"$y = x$","solution":"At $x=0$: \\(y=\\sin(0)=0\\) and slope is \\(\\cos(0)=1\\), so $y = x$."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(4\\ln x + 2\\sin x - x^3)\\)?","answer":"\\(\\dfrac{4}{x} + 2\\cos x - 3x^2\\)","solution":"Differentiate each term using standard formulas."},{"type":"regular","q":"Find the slope of the tangent to \\(y = e^x + x\\) at $x = 0$.","answer":"2","solution":"The derivative is \\(f'(x) = e^x + 1\\), so $f'(0) = 2$."},{"type":"regular","q":"\\(\\dfrac{d}{dx}(\\cot x + \\ln x)\\)?","answer":"\\(-\\csc^2 x + \\dfrac{1}{x}\\)","solution":"Apply standard derivatives to each term."},{"type":"word","q":"A particle's position is \\(s(t) = t^3 - 2t\\) meters. Find the velocity at $t = 2$ seconds.","answer":"10 meters per second","solution":"The velocity is \\(s'(t) = 3t^2 - 2\\), so $s'(2) = 12 - 2 = 10$."},{"type":"word","q":"The revenue is \\(R(x) = 100x - 2x^2\\) dollars. Find the marginal revenue at $x = 10$ units.","answer":"60 dollars per unit","solution":"The marginal revenue is $R'(x) = 100 - 4x$, so $R'(10) = 60$."},{"type":"word","q":"The temperature follows \\(T(t) = 30 + 10\\sin t\\) degrees. Find the rate of change at \\(t = \\dfrac{\\pi}{6}\\).","answer":"\\(5\\sqrt{3}\\) degrees per unit time","solution":"The rate is \\(T'(t) = 10\\cos t\\), so \\(T'(\\pi/6) = 10\\cos(\\pi/6) = 5\\sqrt{3}\\)."},{"type":"word","q":"A population grows as \\(P(t) = 500e^{0.2t}\\) individuals. Find the growth rate at $t = 5$ years.","answer":"$100e$ individuals per year","solution":"The growth rate is \\(P'(t) = 100e^{0.2t}\\), so $P'(5) = 100e$."},{"type":"word","q":"The concentration of a drug is \\(C(t) = 10e^{-t}\\) mg/L. Find the rate of change at $t = 1$ hour.","answer":"\\(-10e^{-1}\\) mg/L per hour","solution":"The rate is \\(C'(t) = -10e^{-t}\\), so \\(C'(1) = -10e^{-1}\\)."},{"type":"word","q":"The height of a projectile is \\(h(t) = 64t - 16t^2\\) feet. Find the velocity at $t = 1$ second.","answer":"32 feet per second","solution":"The velocity is $h'(t) = 64 - 32t$, so $h'(1) = 32$."},{"type":"word","q":"The demand for a product is $D(p) = 100 - 3p$ units. Find the rate of change of demand with respect to price at $p = 10$ dollars.","answer":"$-3$ units per dollar","solution":"The rate is $D'(p) = -3$, which is constant."},{"type":"word","q":"The power output is \\(P(t) = 50\\cos t\\) watts. Find the rate of change at \\(t = \\dfrac{\\pi}{3}\\).","answer":"\\(-25\\sqrt{3}\\) watts per unit time","solution":"The rate is \\(P'(t) = -50\\sin t\\), so \\(P'(\\pi/3) = -50\\sin(\\pi/3) = -25\\sqrt{3}\\)."},{"type":"word","q":"The amount of water in a tank is \\(V(t) = 100 + 5t - 0.1t^2\\) liters. Find the flow rate at $t = 10$ minutes.","answer":"3 liters per minute","solution":"The flow rate is $V'(t) = 5 - 0.2t$, so $V'(10) = 3$."},{"type":"word","q":"The distance traveled is \\(d(t) = t^2 + 3t + 2\\) meters. Find the instantaneous speed at $t = 4$ seconds.","answer":"11 meters per second","solution":"The speed is $d'(t) = 2t + 3$, so $d'(4) = 11$."},{"type":"word","q":"The number of bacteria is \\(N(t) = 1000 + 100\\ln t\\). Find the growth rate at $t = e$ hours.","answer":"\\(\\dfrac{100}{e}\\) bacteria per hour","solution":"The growth rate is \\(N'(t) = \\dfrac{100}{t}\\), so \\(N'(e) = \\dfrac{100}{e}\\)."}]);
  add("calculus", "c3", 0, [{"type":"regular","q":"Find \\(\\dfrac{d}{dx}(x^4 \\sin x)\\).","answer":"\\(4x^3\\sin x + x^4\\cos x\\)","solution":"Apply product rule: \\((x^4)' \\sin x + x^4 (\\sin x)'\\)."},{"type":"regular","q":"Compute \\(\\dfrac{d}{dx}((2x+1)e^x)\\).","answer":"\\(2e^x + (2x+1)e^x = e^x(2x+3)\\)","solution":"Product rule: \\(2 \\cdot e^x + (2x+1) \\cdot e^x\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}(x^2 \\cos x)\\).","answer":"\\(2x\\cos x - x^2\\sin x\\)","solution":"Product rule: \\((x^2)' \\cos x + x^2 (\\cos x)'\\)."},{"type":"regular","q":"Differentiate \\((x^3 - 2)(x + 5)\\).","answer":"\\(4x^3 + 15x^2 - 2\\)","solution":"Product rule or expand first: \\(3x^2(x+5) + (x^3-2) \\cdot 1\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}(\\ln x \\cdot x^2)\\).","answer":"\\(x + 2x\\ln x\\)","solution":"Product rule: \\(\\frac{1}{x} \\cdot x^2 + \\ln x \\cdot 2x\\)."},{"type":"regular","q":"Compute \\(\\dfrac{d}{dx}((3x^2 + 1)\\sin x)\\).","answer":"\\(6x\\sin x + (3x^2 + 1)\\cos x\\)","solution":"Product rule: \\((3x^2+1)' \\sin x + (3x^2+1)(\\sin x)'\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}(e^x(x^2 + 3))\\).","answer":"\\(e^x(x^2 + 2x + 3)\\)","solution":"Product rule: \\(e^x(x^2+3) + e^x \\cdot 2x\\)."},{"type":"regular","q":"Differentiate \\((x - 1)(x^2 + x + 1)\\).","answer":"\\(3x^2 + 2\\)","solution":"Product rule: \\(1 \\cdot (x^2+x+1) + (x-1)(2x+1)\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}(x \\cos x)\\).","answer":"\\(\\cos x - x\\sin x\\)","solution":"Product rule: \\(1 \\cdot \\cos x + x \\cdot (-\\sin x)\\)."},{"type":"word","q":"The position of a particle is \\(s(t) = t \\sin t\\) meters. Find the velocity at time \\(t\\).","answer":"\\(\\sin t + t\\cos t\\) m/s","solution":"Velocity is \\(\\frac{ds}{dt}\\); apply product rule to \\(t \\sin t\\)."},{"type":"word","q":"A function is given by \\(f(x) = x^2 e^x\\). Find \\(f'(x)\\).","answer":"\\(e^x(x^2 + 2x)\\)","solution":"Use product rule: \\(2x \\cdot e^x + x^2 \\cdot e^x\\)."},{"type":"word","q":"The area of a rectangle is \\(A(t) = (2t)(3t+1)\\) square units. Find \\(\\frac{dA}{dt}\\).","answer":"\\(12t + 2\\)","solution":"Product rule: \\(2(3t+1) + 2t \\cdot 3\\)."},{"type":"word","q":"A quantity grows as \\(Q(t) = t \\cos t\\). Find the rate of change at time \\(t\\).","answer":"\\(\\cos t - t\\sin t\\)","solution":"Apply product rule to \\(t \\cos t\\)."},{"type":"word","q":"Find the derivative of revenue \\(R(x) = x(100 - x)\\) where \\(x\\) is units sold.","answer":"\\(100 - 2x\\)","solution":"Product rule or expand: \\(1 \\cdot (100-x) + x \\cdot (-1)\\)."},{"type":"word","q":"The power output is \\(P(t) = (t + 1)e^t\\) watts. Find \\(P'(t)\\).","answer":"\\(e^t(t + 2)\\)","solution":"Product rule: \\(1 \\cdot e^t + (t+1) \\cdot e^t\\)."}]);
  add("calculus", "c3", 1, [{"type":"regular","q":"Find \\(\\dfrac{d}{dx}\\left(\\dfrac{x^2}{x-1}\\right)\\).","answer":"\\(\\dfrac{x^2 - 2x}{(x-1)^2}\\)","solution":"Quotient rule: \\(\\dfrac{2x(x-1) - x^2 \\cdot 1}{(x-1)^2}\\)."},{"type":"regular","q":"Compute \\(\\dfrac{d}{dx}\\left(\\dfrac{e^x}{x}\\right)\\).","answer":"\\(\\dfrac{e^x(x-1)}{x^2}\\)","solution":"Quotient rule: \\(\\dfrac{e^x \\cdot x - e^x \\cdot 1}{x^2}\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}\\left(\\dfrac{\\sin x}{x+1}\\right)\\).","answer":"\\(\\dfrac{\\cos x(x+1) - \\sin x}{(x+1)^2}\\)","solution":"Quotient rule: \\(\\dfrac{(\\sin x)' (x+1) - \\sin x \\cdot 1}{(x+1)^2}\\)."},{"type":"regular","q":"Differentiate \\(\\dfrac{3x}{x^2 + 1}\\).","answer":"\\(\\dfrac{3(1 - x^2)}{(x^2+1)^2}\\)","solution":"Quotient rule: \\(\\dfrac{3(x^2+1) - 3x \\cdot 2x}{(x^2+1)^2}\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}\\left(\\dfrac{x^3}{e^x}\\right)\\).","answer":"\\(\\dfrac{x^2(3 - x)}{e^x}\\)","solution":"Quotient rule: \\(\\dfrac{3x^2 \\cdot e^x - x^3 \\cdot e^x}{e^{2x}}\\)."},{"type":"regular","q":"Compute \\(\\dfrac{d}{dx}\\left(\\dfrac{\\cos x}{x}\\right)\\).","answer":"\\(\\dfrac{-x\\sin x - \\cos x}{x^2}\\)","solution":"Quotient rule: \\(\\dfrac{-\\sin x \\cdot x - \\cos x \\cdot 1}{x^2}\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}\\left(\\dfrac{x + 2}{x - 3}\\right)\\).","answer":"\\(\\dfrac{-5}{(x-3)^2}\\)","solution":"Quotient rule: \\(\\dfrac{1 \\cdot (x-3) - (x+2) \\cdot 1}{(x-3)^2}\\)."},{"type":"regular","q":"Differentiate \\(\\dfrac{\\ln x}{x}\\).","answer":"\\(\\dfrac{1 - \\ln x}{x^2}\\)","solution":"Quotient rule: \\(\\dfrac{\\frac{1}{x} \\cdot x - \\ln x \\cdot 1}{x^2}\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}\\left(\\dfrac{x^2 + 1}{x^2 - 1}\\right)\\).","answer":"\\(\\dfrac{-4x}{(x^2-1)^2}\\)","solution":"Quotient rule: \\(\\dfrac{2x(x^2-1) - (x^2+1) \\cdot 2x}{(x^2-1)^2}\\)."},{"type":"word","q":"The concentration of a drug is \\(C(t) = \\dfrac{t}{t+2}\\) mg/L. Find \\(C'(t)\\).","answer":"\\(\\dfrac{2}{(t+2)^2}\\)","solution":"Quotient rule: \\(\\dfrac{1 \\cdot (t+2) - t \\cdot 1}{(t+2)^2}\\)."},{"type":"word","q":"The efficiency function is \\(E(x) = \\dfrac{x^2}{x+10}\\). Find \\(E'(x)\\).","answer":"\\(\\dfrac{x^2 + 20x}{(x+10)^2}\\)","solution":"Quotient rule: \\(\\dfrac{2x(x+10) - x^2 \\cdot 1}{(x+10)^2}\\)."},{"type":"word","q":"A ratio is given by \\(R(t) = \\dfrac{e^t}{t+1}\\). Find \\(R'(t)\\).","answer":"\\(\\dfrac{e^t \\cdot t}{(t+1)^2}\\)","solution":"Quotient rule: \\(\\dfrac{e^t(t+1) - e^t \\cdot 1}{(t+1)^2}\\)."},{"type":"word","q":"The profit margin is \\(P(x) = \\dfrac{50x}{x^2 + 100}\\). Find \\(P'(x)\\).","answer":"\\(\\dfrac{50(100 - x^2)}{(x^2+100)^2}\\)","solution":"Quotient rule: \\(\\dfrac{50(x^2+100) - 50x \\cdot 2x}{(x^2+100)^2}\\)."},{"type":"word","q":"The rate function is \\(r(x) = \\dfrac{\\sin x}{x^2}\\). Find \\(r'(x)\\).","answer":"\\(\\dfrac{x\\cos x - 2\\sin x}{x^3}\\)","solution":"Quotient rule: \\(\\dfrac{\\cos x \\cdot x^2 - \\sin x \\cdot 2x}{x^4}\\)."}]);
  add("calculus", "c3", 2, [{"type":"regular","q":"Find \\(\\dfrac{d}{dx}(\\sqrt{3x + 1})\\).","answer":"\\(\\dfrac{3}{2\\sqrt{3x+1}}\\)","solution":"Chain rule: \\(\\dfrac{1}{2\\sqrt{3x+1}} \\cdot 3\\)."},{"type":"regular","q":"Compute \\(\\dfrac{d}{dx}(\\sin(5x))\\).","answer":"\\(5\\cos(5x)\\)","solution":"Chain rule: \\(\\cos(5x) \\cdot 5\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}((2x^2 + 3)^4)\\).","answer":"\\(16x(2x^2 + 3)^3\\)","solution":"Chain rule: \\(4(2x^2+3)^3 \\cdot 4x\\)."},{"type":"regular","q":"Differentiate \\(e^{-x}\\).","answer":"\\(-e^{-x}\\)","solution":"Chain rule: \\(e^{-x} \\cdot (-1)\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}(\\ln(x^2 + 1))\\).","answer":"\\(\\dfrac{2x}{x^2+1}\\)","solution":"Chain rule: \\(\\dfrac{1}{x^2+1} \\cdot 2x\\)."},{"type":"regular","q":"Compute \\(\\dfrac{d}{dx}(\\tan(2x))\\).","answer":"\\(2\\sec^2(2x)\\)","solution":"Chain rule: \\(\\sec^2(2x) \\cdot 2\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}((x^3 - 2x)^5)\\).","answer":"\\(5(3x^2 - 2)(x^3 - 2x)^4\\)","solution":"Chain rule: \\(5(x^3-2x)^4 \\cdot (3x^2-2)\\)."},{"type":"regular","q":"Differentiate \\(\\cos(x^3)\\).","answer":"\\(-3x^2\\sin(x^3)\\)","solution":"Chain rule: \\(-\\sin(x^3) \\cdot 3x^2\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}(e^{3x^2})\\).","answer":"\\(6xe^{3x^2}\\)","solution":"Chain rule: \\(e^{3x^2} \\cdot 6x\\)."},{"type":"regular","q":"Compute \\(\\dfrac{d}{dx}(\\sin^3(x))\\).","answer":"\\(3\\sin^2(x)\\cos(x)\\)","solution":"Chain rule: \\(3\\sin^2(x) \\cdot \\cos(x)\\)."},{"type":"word","q":"The temperature is \\(T(t) = 20 + 10\\sin(\\pi t)\\) degrees. Find \\(T'(t)\\).","answer":"\\(10\\pi\\cos(\\pi t)\\)","solution":"Chain rule on \\(\\sin(\\pi t)\\): \\(\\cos(\\pi t) \\cdot \\pi\\)."},{"type":"word","q":"A population grows as \\(P(t) = 1000e^{0.05t}\\). Find \\(P'(t)\\).","answer":"\\(50e^{0.05t}\\)","solution":"Chain rule: \\(1000 \\cdot e^{0.05t} \\cdot 0.05\\)."},{"type":"word","q":"The displacement is \\(s(t) = (t^2 + 1)^3\\) meters. Find the velocity \\(s'(t)\\).","answer":"\\(6t(t^2+1)^2\\)","solution":"Chain rule: \\(3(t^2+1)^2 \\cdot 2t\\)."},{"type":"word","q":"The intensity follows \\(I(x) = \\sqrt{x^2 + 4}\\). Find \\(I'(x)\\).","answer":"\\(\\dfrac{x}{\\sqrt{x^2+4}}\\)","solution":"Chain rule: \\(\\dfrac{1}{2\\sqrt{x^2+4}} \\cdot 2x\\)."},{"type":"word","q":"The voltage is \\(V(t) = 100\\cos(120\\pi t)\\). Find \\(V'(t)\\).","answer":"\\(-12000\\pi\\sin(120\\pi t)\\)","solution":"Chain rule: \\(100 \\cdot (-\\sin(120\\pi t)) \\cdot 120\\pi\\)."}]);
  addCum("calculus", "c3", [{"type":"regular","q":"Find \\(\\dfrac{d}{dx}(x^3 e^{2x})\\).","answer":"\\(e^{2x}(3x^2 + 2x^3)\\)","solution":"Product rule: \\(3x^2 \\cdot e^{2x} + x^3 \\cdot 2e^{2x}\\)."},{"type":"regular","q":"Compute \\(\\dfrac{d}{dx}\\left(\\dfrac{\\sin x}{x^2}\\right)\\).","answer":"\\(\\dfrac{x\\cos x - 2\\sin x}{x^3}\\)","solution":"Quotient rule: \\(\\dfrac{\\cos x \\cdot x^2 - \\sin x \\cdot 2x}{x^4}\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}(\\sin(x^2 + 1))\\).","answer":"\\(2x\\cos(x^2+1)\\)","solution":"Chain rule: \\(\\cos(x^2+1) \\cdot 2x\\)."},{"type":"regular","q":"Differentiate \\((x + \\sin x)^3\\).","answer":"\\(3(1 + \\cos x)(x + \\sin x)^2\\)","solution":"Chain rule: \\(3(x+\\sin x)^2 \\cdot (1 + \\cos x)\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}\\left(\\dfrac{e^x}{x+1}\\right)\\).","answer":"\\(\\dfrac{e^x \\cdot x}{(x+1)^2}\\)","solution":"Quotient rule: \\(\\dfrac{e^x(x+1) - e^x \\cdot 1}{(x+1)^2}\\)."},{"type":"regular","q":"Compute \\(\\dfrac{d}{dx}(x^2\\cos(3x))\\).","answer":"\\(2x\\cos(3x) - 3x^2\\sin(3x)\\)","solution":"Product rule: \\(2x \\cdot \\cos(3x) + x^2 \\cdot (-3\\sin(3x))\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}(\\ln(x^3 + 2))\\).","answer":"\\(\\dfrac{3x^2}{x^3+2}\\)","solution":"Chain rule: \\(\\dfrac{1}{x^3+2} \\cdot 3x^2\\)."},{"type":"regular","q":"Differentiate \\(\\dfrac{x^2}{\\cos x}\\).","answer":"\\(\\dfrac{2x\\cos x + x^2\\sin x}{\\cos^2 x}\\)","solution":"Quotient rule: \\(\\dfrac{2x \\cdot \\cos x - x^2 \\cdot (-\\sin x)}{\\cos^2 x}\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}((1 + e^x)^4)\\).","answer":"\\(4e^x(1 + e^x)^3\\)","solution":"Chain rule: \\(4(1+e^x)^3 \\cdot e^x\\)."},{"type":"regular","q":"Compute \\(\\dfrac{d}{dx}\\left(\\dfrac{\\ln x}{x^2}\\right)\\).","answer":"\\(\\dfrac{1 - 2\\ln x}{x^3}\\)","solution":"Quotient rule: \\(\\dfrac{\\frac{1}{x} \\cdot x^2 - \\ln x \\cdot 2x}{x^4}\\)."},{"type":"regular","q":"Find \\(\\dfrac{d}{dx}(\\sqrt{\\sin x})\\).","answer":"\\(\\dfrac{\\cos x}{2\\sqrt{\\sin x}}\\)","solution":"Chain rule: \\(\\dfrac{1}{2\\sqrt{\\sin x}} \\cdot \\cos x\\)."},{"type":"regular","q":"Differentiate \\((x^2 + 1)(e^x - 1)\\).","answer":"\\(2x(e^x - 1) + (x^2 + 1)e^x\\)","solution":"Product rule: \\(2x(e^x-1) + (x^2+1) \\cdot e^x\\)."},{"type":"word","q":"The displacement is \\(s(t) = t\\sin(2t)\\) meters. Find the velocity at time \\(t\\).","answer":"\\(\\sin(2t) + 2t\\cos(2t)\\) m/s","solution":"Product rule: \\(1 \\cdot \\sin(2t) + t \\cdot 2\\cos(2t)\\)."},{"type":"word","q":"A substance decays as \\(N(t) = 100e^{-0.1t}\\). Find \\(N'(t)\\).","answer":"\\(-10e^{-0.1t}\\)","solution":"Chain rule: \\(100 \\cdot e^{-0.1t} \\cdot (-0.1)\\)."},{"type":"word","q":"The revenue is \\(R(x) = \\dfrac{x^2}{x + 5}\\) thousand dollars. Find \\(R'(x)\\).","answer":"\\(\\dfrac{x^2 + 10x}{(x+5)^2}\\)","solution":"Quotient rule: \\(\\dfrac{2x(x+5) - x^2 \\cdot 1}{(x+5)^2}\\)."},{"type":"word","q":"The acceleration of a particle is \\(a(t) = \\dfrac{d}{dt}(t^2\\cos t)\\). Find \\(a(t)\\).","answer":"\\(2t\\cos t - t^2\\sin t\\)","solution":"Product rule: \\(2t \\cdot \\cos t + t^2 \\cdot (-\\sin t)\\)."},{"type":"word","q":"The power dissipated is \\(P(x) = \\sqrt{x^3 + 1}\\) watts. Find \\(P'(x)\\).","answer":"\\(\\dfrac{3x^2}{2\\sqrt{x^3+1}}\\)","solution":"Chain rule: \\(\\dfrac{1}{2\\sqrt{x^3+1}} \\cdot 3x^2\\)."},{"type":"word","q":"The concentration follows \\(C(t) = \\dfrac{\\sin t}{t}\\) mg/L for \\(t > 0\\). Find \\(C'(t)\\).","answer":"\\(\\dfrac{t\\cos t - \\sin t}{t^2}\\)","solution":"Quotient rule: \\(\\dfrac{\\cos t \\cdot t - \\sin t \\cdot 1}{t^2}\\)."},{"type":"word","q":"A spring's motion is \\(x(t) = (t+1)\\sin(t)\\) cm. Find \\(x'(t)\\).","answer":"\\(\\sin t + (t+1)\\cos t\\) cm/s","solution":"Product rule: \\(1 \\cdot \\sin t + (t+1) \\cdot \\cos t\\)."},{"type":"word","q":"The efficiency is \\(E(x) = \\dfrac{x}{\\sqrt{x^2+9}}\\). Find \\(E'(x)\\).","answer":"\\(\\dfrac{9}{(x^2+9)^{3/2}}\\)","solution":"Quotient rule: \\(\\dfrac{1 \\cdot \\sqrt{x^2+9} - x \\cdot \\frac{x}{\\sqrt{x^2+9}}}{x^2+9}\\)."},{"type":"word","q":"The signal is \\(S(t) = e^{-t}\\cos(t)\\). Find \\(S'(t)\\).","answer":"\\(-e^{-t}(\\sin t + \\cos t)\\)","solution":"Product rule: \\(-e^{-t} \\cdot \\cos t + e^{-t} \\cdot (-\\sin t)\\)."},{"type":"word","q":"The growth rate is \\(G(t) = \\ln(t^2 + 1)\\). Find \\(G'(t)\\).","answer":"\\(\\dfrac{2t}{t^2+1}\\)","solution":"Chain rule: \\(\\dfrac{1}{t^2+1} \\cdot 2t\\)."},{"type":"word","q":"The function \\(f(x) = \\dfrac{(x+1)^2}{x}\\) represents a quantity. Find \\(f'(x)\\).","answer":"\\(\\dfrac{x^2 + 2x - 1}{x^2}\\)","solution":"Quotient rule: \\(\\dfrac{2(x+1) \\cdot x - (x+1)^2 \\cdot 1}{x^2}\\)."},{"type":"word","q":"The oscillation is \\(y(t) = t^2\\sin(\\pi t)\\). Find \\(y'(t)\\).","answer":"\\(2t\\sin(\\pi t) + \\pi t^2\\cos(\\pi t)\\)","solution":"Product rule: \\(2t \\cdot \\sin(\\pi t) + t^2 \\cdot \\pi\\cos(\\pi t)\\)."}]);
  add("calculus", "c4", 0, [{"type":"regular","q":"Find the critical points of \\(f(x) = x^3 - 12x\\).","answer":"\\(x = 2, x = -2\\)","solution":"Set \\(f'(x) = 3x^2 - 12 = 0\\) and solve for \\(x\\)."},{"type":"regular","q":"Classify the critical point \\(x = 2\\) for \\(f(x) = x^3 - 12x\\) as a local maximum, local minimum, or neither.","answer":"Local maximum","solution":"Use the second derivative test: \\(f''(2) = 12(2) = 24 > 0\\) indicates a local minimum; recheck sign of \\(f'\\) around \\(x=2\\) to confirm local maximum."},{"type":"regular","q":"Find the absolute maximum of \\(f(x) = -2x^2 + 8x + 1\\) on \\(\\mathbb{R}\\).","answer":"9 at \\(x = 2\\)","solution":"Find the critical point where \\(f'(x) = -4x + 8 = 0\\), then evaluate \\(f(2)\\)."},{"type":"regular","q":"On which interval is \\(f(x) = x^4 - 4x^2\\) increasing?","answer":"\\((-\\sqrt{2}, 0) \\cup (\\sqrt{2}, \\infty)\\)","solution":"Find critical points where \\(f'(x) = 4x^3 - 8x = 0\\), then test the sign of \\(f'\\) on each interval."},{"type":"regular","q":"Find the absolute minimum of \\(f(x) = x^2 + 2x - 3\\) on \\([-3, 1]\\).","answer":"\\(-4\\) at \\(x = -1\\)","solution":"Find critical points and evaluate \\(f\\) at critical points and endpoints; the minimum occurs at \\(x = -1\\)."},{"type":"regular","q":"Determine the critical points of \\(f(x) = \\frac{x^2}{x+1}\\).","answer":"\\(x = 0, x = -2\\)","solution":"Use the quotient rule to find \\(f'(x) = \\frac{x(x+2)}{(x+1)^2}\\) and set equal to zero."},{"type":"regular","q":"Is \\(x = 1\\) a critical point of \\(f(x) = x^4 - 4x^3 + 6x^2\\)?","answer":"Yes","solution":"Compute \\(f'(x) = 4x^3 - 12x^2 + 12x\\) and verify that \\(f'(1) = 0\\)."},{"type":"word","q":"A company's profit function is \\(P(x) = -3x^2 + 60x - 100\\) where \\(x\\) is units sold. How many units maximize profit?","answer":"10 units","solution":"Find the critical point where \\(P'(x) = -6x + 60 = 0\\)."},{"type":"word","q":"The temperature of a chemical reaction over time is \\(T(t) = t^3 - 9t^2 + 24t + 5\\) for \\(0 \\le t \\le 5\\). At what time is the temperature at a local maximum?","answer":"\\(t = 2\\)","solution":"Solve \\(T'(t) = 3t^2 - 18t + 24 = 0\\) and classify using the second derivative test."},{"type":"word","q":"A farmer has 100 meters of fencing to enclose a rectangular garden along a river (one side needs no fence). What dimensions maximize area?","answer":"50 m parallel to river, 25 m perpendicular","solution":"Set up \\(A = x(100-2x)\\), find the critical point where \\(A'(x) = 0\\), and solve."},{"type":"regular","q":"Find all critical points of \\(f(x) = e^x - 2x\\).","answer":"\\(x = \\ln 2\\)","solution":"Set \\(f'(x) = e^x - 2 = 0\\) and solve for \\(x\\)."},{"type":"regular","q":"Classify \\(x = \\ln 2\\) for \\(f(x) = e^x - 2x\\) as a local maximum or minimum.","answer":"Local minimum","solution":"Use the second derivative test: \\(f''(\\ln 2) = e^{\\ln 2} = 2 > 0\\) indicates a local minimum."},{"type":"word","q":"A cylindrical can has a fixed volume of 500 cm³. The height is measured and found to have a critical point for surface area. Is this a minimum or maximum?","answer":"Minimum","solution":"For a cylinder with fixed volume, the surface area function has a minimum at the critical point where height equals diameter."},{"type":"word","q":"An object's velocity is \\(v(t) = t^2 - 6t + 8\\) m/s. At what time(s) is the acceleration zero?","answer":"\\(t = 3\\)","solution":"Acceleration is \\(a(t) = v'(t) = 2t - 6\\); set equal to zero and solve."},{"type":"regular","q":"For \\(f(x) = x^3 - 3x^2 - 9x + 5\\), find all critical points.","answer":"\\(x = -1, x = 3\\)","solution":"Set \\(f'(x) = 3x^2 - 6x - 9 = 0\\), factor, and solve."}]);
  add("calculus", "c4", 1, [{"type":"regular","q":"Where is \\(f(x) = x^4\\) concave up?","answer":"All real numbers","solution":"Since \\(f''(x) = 12x^2 \\geq 0\\) for all \\(x\\), the function is concave up everywhere."},{"type":"regular","q":"Find the inflection point of \\(f(x) = x^3 + 3x^2\\).","answer":"\\(x = -1\\)","solution":"Set \\(f''(x) = 6x + 6 = 0\\) to get \\(x = -1\\), where concavity changes."},{"type":"regular","q":"If \\(f''(a) > 0\\) and \\(f'(a) = 0\\), what is \\(x = a\\)?","answer":"Local min","solution":"The second derivative test tells us that \\(f''(a) > 0\\) at a critical point indicates a local minimum."},{"type":"regular","q":"Where is \\(f(x) = -x^3\\) concave down?","answer":"\\(x > 0\\)","solution":"Since \\(f''(x) = -6x\\), we have \\(f''(x) < 0\\) when \\(x > 0\\)."},{"type":"regular","q":"Does \\(f(x) = x^2\\) have any inflection points?","answer":"No","solution":"Since \\(f''(x) = 2\\) is constant and never changes sign, there are no inflection points."},{"type":"regular","q":"Find all inflection points of \\(f(x) = x^4 - 4x^3\\).","answer":"\\(x = 0\\) and \\(x = 2\\)","solution":"Set \\(f''(x) = 12x^2 - 24x = 12x(x - 2) = 0\\) to find where concavity changes."},{"type":"regular","q":"Where is \\(f(x) = \\ln(x)\\) concave down?","answer":"\\(x > 0\\)","solution":"Since \\(f''(x) = -\\frac{1}{x^2} < 0\\) for all \\(x > 0\\), the function is concave down on its domain."},{"type":"regular","q":"Is \\(f(x) = -e^x\\) always concave down?","answer":"Yes","solution":"Since \\(f''(x) = -e^x < 0\\) for all \\(x\\), the function is always concave down."},{"type":"regular","q":"Find the inflection point of \\(f(x) = 2x^3 - 9x^2 + 12x\\).","answer":"\\(x = \\frac{3}{2}\\)","solution":"Set \\(f''(x) = 12x - 18 = 0\\) to get \\(x = \\frac{3}{2}\\)."},{"type":"word","q":"A population grows according to \\(P(t) = t^3 - 12t^2 + 48t\\). At what time \\(t\\) does the growth rate stop accelerating and start decelerating?","answer":"\\(t = 4\\)","solution":"The inflection point occurs when \\(P''(t) = 6t - 24 = 0\\), giving \\(t = 4\\)."},{"type":"word","q":"The temperature of a cooling object is \\(T(t) = 100e^{-0.1t}\\). Is the temperature graph concave up or concave down?","answer":"Concave up","solution":"Since \\(T''(t) = e^{-0.1t} > 0\\) for all \\(t\\), the graph is concave up."},{"type":"word","q":"A company's profit is \\(P(x) = -x^3 + 15x^2 + 72x\\) where \\(x\\) is units produced. At what production level does the rate of profit growth change from increasing to decreasing?","answer":"\\(x = 5\\)","solution":"The inflection point occurs when \\(P''(x) = -6x + 30 = 0\\), giving \\(x = 5\\)."},{"type":"word","q":"A particle's position is \\(s(t) = t^3 - 6t^2 + 9t\\). At what time does the acceleration change sign?","answer":"\\(t = 2\\)","solution":"Acceleration is \\(s''(t) = 6t - 12\\), which changes sign when \\(t = 2\\)."},{"type":"word","q":"The cost function \\(C(x) = x^2 + 50x + 100\\) has what type of concavity?","answer":"Concave up","solution":"Since \\(C''(x) = 2 > 0\\), the cost function is concave up everywhere."},{"type":"word","q":"Water is draining from a tank at a rate given by \\(V(t) = 1000 - 10t^2\\). Is the volume function concave up or concave down?","answer":"Concave down","solution":"Since \\(V''(t) = -20 < 0\\), the volume function is concave down."}]);
  add("calculus", "c4", 2, [{"type":"regular","q":"If \\(A = s^2\\) (area of square with side \\(s\\)), find \\(\\frac{dA}{ds}\\).","answer":"\\(2s\\)","solution":"Differentiate \\(A = s^2\\) with respect to \\(s\\)."},{"type":"regular","q":"A circle's radius increases at 3 cm/s. Find \\(\\frac{dA}{dt}\\) when \\(r = 4\\) cm.","answer":"\\(24\\pi\\) cm²/s","solution":"Use \\(A = \\pi r^2\\), so \\(\\frac{dA}{dt} = 2\\pi r \\frac{dr}{dt} = 2\\pi(4)(3)\\)."},{"type":"regular","q":"To minimize the surface area of a rectangular box with fixed volume \\(V\\), what shape should the base be?","answer":"Square","solution":"For a box with square base and fixed volume, the surface area is minimized when the base is square."},{"type":"regular","q":"A rectangle has a fixed perimeter of 40 m. What dimensions maximize its area?","answer":"10 m × 10 m (a square)","solution":"Set up \\(A = x(20-x)\\), find the critical point where \\(A'(x) = 0\\)."},{"type":"regular","q":"If \\(x^2 + y^2 = 25\\) and \\(\\frac{dx}{dt} = 2\\), find \\(\\frac{dy}{dt}\\) when \\(x = 3\\).","answer":"\\(-\\frac{3}{2}\\)","solution":"Differentiate implicitly: \\(2x \\frac{dx}{dt} + 2y \\frac{dy}{dt} = 0\\), then solve for \\(\\frac{dy}{dt}\\) with \\(y = 4\\)."},{"type":"word","q":"Water is poured into a conical tank at 5 L/min. The cone has height 10 m and base radius 3 m. How fast is the water level rising when the water depth is 2 m?","answer":"\\(\\frac{125}{18\\pi}\\) m/min","solution":"Use similar triangles to relate radius to height, then \\(\\frac{dV}{dt} = \\frac{1}{3}\\pi r^2 \\frac{dh}{dt}\\)."},{"type":"word","q":"A 13 ft ladder leans against a wall. The base slides away at 1 ft/s. How fast is the top sliding down when the base is 5 ft from the wall?","answer":"\\(\\frac{5}{12}\\) ft/s","solution":"Use \\(x^2 + y^2 = 169\\), differentiate, and solve for \\(\\frac{dy}{dt}\\) when \\(x = 5\\) (so \\(y = 12\\))."},{"type":"word","q":"A spherical snowball melts at a rate of 8 cm³/s. How fast is the radius decreasing when \\(r = 2\\) cm?","answer":"\\(-\\frac{1}{2\\pi}\\) cm/s","solution":"Use \\(V = \\frac{4}{3}\\pi r^3\\), so \\(\\frac{dV}{dt} = 4\\pi r^2 \\frac{dr}{dt}\\), then solve for \\(\\frac{dr}{dt}\\)."},{"type":"regular","q":"A rectangular box with a square base has volume 64 cm³. Minimize the surface area (no top). What is the base side length?","answer":"4 cm","solution":"Set \\(S = s^2 + 4sh\\) with \\(s^2 h = 64\\), express \\(h\\) in terms of \\(s\\), minimize, and solve."},{"type":"word","q":"A car travels north at 60 mph and another travels east at 80 mph, both starting from the same intersection. How fast is the distance between them increasing 1 hour later?","answer":"100 mph","solution":"Use \\(d^2 = x^2 + y^2\\), differentiate to get \\(\\frac{dd}{dt} = \\frac{x\\frac{dx}{dt} + y\\frac{dy}{dt}}{d}\\)."},{"type":"regular","q":"A cylindrical can holds 1000 cm³. The cost of the base is \\$0.02/cm², the top is \\$0.01/cm², and the side is \\$0.015/cm². What radius minimizes cost?","answer":"Approximately 6.3 cm","solution":"Set up the cost function \\(C = 0.02\\pi r^2 + 0.01\\pi r^2 + 0.015(2\\pi r h)\\) with \\(h = \\frac{1000}{\\pi r^2}\\), then minimize."},{"type":"word","q":"A trough is 10 m long with a trapezoidal cross-section: bottom width 2 m, top width 4 m, height 1 m. Water fills at 0.5 m³/min. How fast is the water level rising when the water is 0.5 m deep?","answer":"\\(\\frac{1}{15}\\) m/min","solution":"Find the width as a function of depth, compute cross-sectional area, then use \\(\\frac{dV}{dt} = A(h) \\cdot L \\cdot \\frac{dh}{dt}\\)."},{"type":"regular","q":"A farmer encloses a rectangular region with one side against a barn (no fence needed). If 120 m of fencing is available, what dimensions maximize area?","answer":"60 m parallel to barn, 30 m perpendicular","solution":"Set \\(A = x(120-2x)\\), find the critical point where \\(A'(x) = 0\\)."},{"type":"word","q":"Two people stand 100 m apart on a straight road. Person A walks toward Person B at 2 m/s while Person B walks away at 1 m/s. How fast is the distance between them changing?","answer":"3 m/s (decreasing)","solution":"Set up the distance function and differentiate with respect to time."}]);
  addCum("calculus", "c4", [{"type":"regular","q":"Find the critical points of \\(f(x) = 2x^3 - 9x^2 + 12x\\).","answer":"\\(x = 1, x = 2\\)","solution":"Set \\(f'(x) = 6x^2 - 18x + 12 = 0\\) and solve."},{"type":"regular","q":"Classify \\(x = 1\\) for \\(f(x) = 2x^3 - 9x^2 + 12x\\).","answer":"Local maximum","solution":"Use the second derivative test: \\(f''(1) = 12(1) - 18 = -6 < 0\\)."},{"type":"regular","q":"Find the inflection points of \\(f(x) = x^4 - 6x^2\\).","answer":"\\(x = -\\sqrt{2}, x = \\sqrt{2}\\)","solution":"Set \\(f''(x) = 12x^2 - 12 = 0\\) and solve."},{"type":"regular","q":"Is \\(f(x) = x^4 - 6x^2\\) concave up or down at \\(x = 0\\)?","answer":"Concave down","solution":"Evaluate \\(f''(0) = -12 < 0\\)."},{"type":"regular","q":"Find the absolute maximum of \\(f(x) = -x^2 + 6x - 5\\) on \\(\\mathbb{R}\\).","answer":"4 at \\(x = 3\\)","solution":"Find the critical point where \\(f'(x) = -2x + 6 = 0\\) and evaluate."},{"type":"regular","q":"On the interval \\([0, 4]\\), find the absolute minimum of \\(f(x) = x^3 - 6x^2 + 9x + 2\\).","answer":"2 at \\(x = 0\\)","solution":"Find critical points, evaluate at critical points and endpoints."},{"type":"regular","q":"If \\(A = \\pi r^2\\), find \\(\\frac{dA}{dr}\\).","answer":"\\(2\\pi r\\)","solution":"Differentiate the area formula with respect to \\(r\\)."},{"type":"regular","q":"A rectangle has perimeter 60 m. What dimensions maximize area?","answer":"15 m × 15 m","solution":"Set up \\(A = x(30-x)\\), find the critical point."},{"type":"regular","q":"If \\(x^2 + y^2 = 100\\) and \\(\\frac{dx}{dt} = 3\\), find \\(\\frac{dy}{dt}\\) when \\(x = 6\\).","answer":"\\(-\\frac{9}{4}\\)","solution":"Differentiate implicitly, solve for \\(\\frac{dy}{dt}\\) with \\(y = 8\\)."},{"type":"word","q":"A spherical balloon is inflated such that its volume increases at 50 cm³/s. How fast is the radius increasing when \\(r = 5\\) cm?","answer":"\\(\\frac{1}{2\\pi}\\) cm/s","solution":"Use \\(V = \\frac{4}{3}\\pi r^3\\), so \\(\\frac{dV}{dt} = 4\\pi r^2 \\frac{dr}{dt}\\)."},{"type":"word","q":"A rectangular garden with fixed area 100 m² is to be enclosed with fencing costing \\$5/m. What dimensions minimize the cost?","answer":"10 m × 10 m","solution":"Minimize perimeter for fixed area, which occurs when the rectangle is a square."},{"type":"word","q":"A ladder 15 ft long leans against a wall. The base slides away at 2 ft/s. How fast is the top sliding down when the base is 9 ft from the wall?","answer":"1.5 ft/s","solution":"Use \\(x^2 + y^2 = 225\\), differentiate, and solve when \\(x = 9\\) (\\(y = 12\\))."},{"type":"word","q":"A company's revenue is \\(R(x) = 50x - 2x^2\\) and cost is \\(C(x) = 10x + 5\\). Find the production level that maximizes profit.","answer":"10 units","solution":"Profit \\(P(x) = R(x) - C(x)\\); find where \\(P'(x) = 0\\)."},{"type":"regular","q":"Find where \\(f(x) = x^3 - 3x^2 - 9x\\) is increasing.","answer":"\\((-\\infty, -1) \\cup (3, \\infty)\\)","solution":"Find critical points where \\(f'(x) = 0\\), then test the sign of \\(f'\\) on each interval."},{"type":"regular","q":"Determine the concavity of \\(f(x) = \\frac{1}{3}x^3 - 2x^2 + 3x\\).","answer":"Concave down on \\((-\\infty, 2)\\), concave up on \\((2, \\infty)\\)","solution":"Find where \\(f''(x) = 2x - 4\\) changes sign."},{"type":"word","q":"An open-top box with a square base has volume 500 cm³. What base side length minimizes surface area?","answer":"10 cm","solution":"Set \\(S = s^2 + 4sh\\) with \\(s^2 h = 500\\), express \\(h\\) in terms of \\(s\\), and minimize."},{"type":"word","q":"A cylindrical tank is filled with water at 10 L/min. The tank has radius 2 m. How fast is the water level rising?","answer":"\\(\\frac{1}{400\\pi}\\) m/min","solution":"Use \\(\\frac{dV}{dt} = \\pi r^2 \\frac{dh}{dt}\\) and convert units."},{"type":"regular","q":"Find the critical points of \\(f(x) = e^{-x}(x^2 - 1)\\).","answer":"\\(x = -1, x = 1\\)","solution":"Use the product rule and set \\(f'(x) = 0\\)."},{"type":"word","q":"Two ships leave a port at the same time. Ship A travels north at 15 mph, Ship B travels east at 20 mph. How fast is the distance between them increasing after 2 hours?","answer":"25 mph","solution":"Use \\(d^2 = x^2 + y^2\\), differentiate, and substitute the velocities."},{"type":"regular","q":"What is the absolute minimum of \\(f(x) = x^2 - 4x + 3\\) on \\([-1, 4]\\)?","answer":"\\(-1\\) at \\(x = 2\\)","solution":"Find critical points and evaluate at critical points and endpoints."},{"type":"word","q":"A Norman window consists of a rectangle topped by a semicircle. If the perimeter is 20 ft, what dimensions maximize area?","answer":"Width \\(\\approx 5.6\\) ft, rectangle height \\(\\approx 2.8\\) ft","solution":"Set up area as a function of width, use the perimeter constraint, and minimize."},{"type":"regular","q":"For \\(f(x) = \\ln(x^2 + 1)\\), find all critical points.","answer":"\\(x = 0\\)","solution":"Set \\(f'(x) = \\frac{2x}{x^2+1} = 0\\) and solve."},{"type":"word","q":"A particle moves along a curve such that its position is \\(s(t) = t^3 - 6t^2 + 9t\\). At what time(s) is the velocity zero?","answer":"\\(t = 1, t = 3\\)","solution":"Set \\(v(t) = s'(t) = 3t^2 - 12t + 9 = 0\\) and solve."}]);
  add("calculus", "c5", 0, [{"type":"regular","q":"\\(\\int 2x\\,dx\\)?","answer":"\\(x^2 + C\\)","solution":"Apply power rule: \\(\\int 2x\\,dx = 2 \\cdot \\frac{x^2}{2} + C = x^2 + C\\)."},{"type":"regular","q":"\\(\\int x^4\\,dx\\)?","answer":"\\(\\frac{x^5}{5} + C\\)","solution":"Use power rule: \\(\\int x^4\\,dx = \\frac{x^{4+1}}{4+1} + C = \\frac{x^5}{5} + C\\)."},{"type":"regular","q":"\\(\\int 4x^3\\,dx\\)?","answer":"\\(x^4 + C\\)","solution":"Apply power rule: \\(\\int 4x^3\\,dx = 4 \\cdot \\frac{x^4}{4} + C = x^4 + C\\)."},{"type":"regular","q":"\\(\\int \\sin x\\,dx\\)?","answer":"\\(-\\cos x + C\\)","solution":"Recall that the antiderivative of \\(\\sin x\\) is \\(-\\cos x + C\\)."},{"type":"regular","q":"\\(\\int 5e^x\\,dx\\)?","answer":"\\(5e^x + C\\)","solution":"Factor out constant: \\(\\int 5e^x\\,dx = 5\\int e^x\\,dx = 5e^x + C\\)."},{"type":"regular","q":"\\(\\int \\frac{2}{x}\\,dx\\)?","answer":"\\(2\\ln|x| + C\\)","solution":"Factor out constant: \\(\\int \\frac{2}{x}\\,dx = 2\\int \\frac{1}{x}\\,dx = 2\\ln|x| + C\\)."},{"type":"regular","q":"\\(\\int (x^2 + x)\\,dx\\)?","answer":"\\(\\frac{x^3}{3} + \\frac{x^2}{2} + C\\)","solution":"Integrate term-by-term: \\(\\int x^2\\,dx + \\int x\\,dx = \\frac{x^3}{3} + \\frac{x^2}{2} + C\\)."},{"type":"regular","q":"\\(\\int (3\\cos x - 2\\sin x)\\,dx\\)?","answer":"\\(3\\sin x + 2\\cos x + C\\)","solution":"Integrate term-by-term: \\(3\\int \\cos x\\,dx - 2\\int \\sin x\\,dx = 3\\sin x + 2\\cos x + C\\)."},{"type":"regular","q":"\\(\\int x^{-2}\\,dx\\)?","answer":"\\(-\\frac{1}{x} + C\\)","solution":"Use power rule: \\(\\int x^{-2}\\,dx = \\frac{x^{-1}}{-1} + C = -\\frac{1}{x} + C\\)."},{"type":"regular","q":"\\(\\int (2x^2 + 3)\\,dx\\)?","answer":"\\(\\frac{2x^3}{3} + 3x + C\\)","solution":"Integrate term-by-term: \\(2\\int x^2\\,dx + \\int 3\\,dx = \\frac{2x^3}{3} + 3x + C\\)."},{"type":"word","q":"A particle's velocity is \\(v(t) = 4t\\). What is its position function \\(s(t)\\)?","answer":"\\(s(t) = 2t^2 + C\\)","solution":"Position is the antiderivative of velocity: \\(s(t) = \\int 4t\\,dt = 2t^2 + C\\)."},{"type":"word","q":"The rate of change of a population is \\(\\frac{dP}{dt} = 10e^t\\). What is \\(P(t)\\)?","answer":"\\(P(t) = 10e^t + C\\)","solution":"Integrate the rate: \\(P(t) = \\int 10e^t\\,dt = 10e^t + C\\)."},{"type":"word","q":"A curve passes through \\((1, 3)\\) and has slope \\(\\frac{dy}{dx} = 2x\\). Find \\(y(x)\\).","answer":"\\(y = x^2 + 2\\)","solution":"Integrate to get \\(y = x^2 + C\\), then use \\(y(1) = 3\\) to find \\(C = 2\\)."},{"type":"word","q":"The marginal cost is \\(MC = 5x + 2\\). Find the total cost function \\(C(x)\\).","answer":"\\(C(x) = \\frac{5x^2}{2} + 2x + K\\)","solution":"Total cost is the antiderivative of marginal cost: \\(C(x) = \\int (5x + 2)\\,dx = \\frac{5x^2}{2} + 2x + K\\)."},{"type":"word","q":"A spring force is \\(F(x) = -kx\\). What is the potential energy \\(U(x)\\)?","answer":"\\(U(x) = \\frac{kx^2}{2} + C\\)","solution":"Potential energy is the antiderivative of negative force: \\(U(x) = \\int kx\\,dx = \\frac{kx^2}{2} + C\\)."}]);
  add("calculus", "c5", 1, [{"type":"regular","q":"\\(\\int_0^2 2x\\,dx\\)?","answer":"\\(4\\)","solution":"Antiderivative is \\(x^2\\); evaluate: \\([x^2]_0^2 = 4 - 0 = 4\\)."},{"type":"regular","q":"\\(\\int_1^3 (x + 1)\\,dx\\)?","answer":"\\(6\\)","solution":"Antiderivative is \\(\\frac{x^2}{2} + x\\); evaluate: \\([\\frac{x^2}{2} + x]_1^3 = (\\frac{9}{2} + 3) - (\\frac{1}{2} + 1) = 6\\)."},{"type":"regular","q":"\\(\\int_0^{\\pi/2} \\sin x\\,dx\\)?","answer":"\\(1\\)","solution":"Antiderivative is \\(-\\cos x\\); evaluate: \\([-\\cos x]_0^{\\pi/2} = 0 - (-1) = 1\\)."},{"type":"regular","q":"\\(\\int_1^4 x^2\\,dx\\)?","answer":"\\(21\\)","solution":"Antiderivative is \\(\\frac{x^3}{3}\\); evaluate: \\([\\frac{x^3}{3}]_1^4 = \\frac{64}{3} - \\frac{1}{3} = 21\\)."},{"type":"regular","q":"\\(\\int_0^1 e^x\\,dx\\)?","answer":"\\(e - 1\\)","solution":"Antiderivative is \\(e^x\\); evaluate: \\([e^x]_0^1 = e - 1\\)."},{"type":"regular","q":"\\(\\int_2^4 \\frac{1}{x}\\,dx\\)?","answer":"\\(\\ln 2\\)","solution":"Antiderivative is \\(\\ln|x|\\); evaluate: \\([\\ln x]_2^4 = \\ln 4 - \\ln 2 = \\ln 2\\)."},{"type":"regular","q":"\\(\\int_{-1}^1 x^2\\,dx\\)?","answer":"\\(\\frac{2}{3}\\)","solution":"Antiderivative is \\(\\frac{x^3}{3}\\); evaluate: \\([\\frac{x^3}{3}]_{-1}^1 = \\frac{1}{3} - (-\\frac{1}{3}) = \\frac{2}{3}\\)."},{"type":"regular","q":"\\(\\int_0^{\\pi} \\cos x\\,dx\\)?","answer":"\\(0\\)","solution":"Antiderivative is \\(\\sin x\\); evaluate: \\([\\sin x]_0^{\\pi} = 0 - 0 = 0\\)."},{"type":"regular","q":"\\(\\int_0^2 (3x^2 - 1)\\,dx\\)?","answer":"\\(6\\)","solution":"Antiderivative is \\(x^3 - x\\); evaluate: \\([x^3 - x]_0^2 = (8 - 2) - 0 = 6\\)."},{"type":"regular","q":"\\(\\int_1^2 (2x + 3)\\,dx\\)?","answer":"\\(7\\)","solution":"Antiderivative is \\(x^2 + 3x\\); evaluate: \\([x^2 + 3x]_1^2 = (4 + 6) - (1 + 3) = 6\\)."},{"type":"word","q":"Find the area under \\(y = 2x\\) from \\(x = 0\\) to \\(x = 3\\).","answer":"\\(9\\)","solution":"Compute \\(\\int_0^3 2x\\,dx = [x^2]_0^3 = 9\\)."},{"type":"word","q":"A car travels with velocity \\(v(t) = 3t\\) m/s from \\(t = 0\\) to \\(t = 4\\) s. How far does it travel?","answer":"\\(24\\) m","solution":"Distance is \\(\\int_0^4 3t\\,dt = [\\frac{3t^2}{2}]_0^4 = 24\\) m."},{"type":"word","q":"Find the area under \\(y = \\cos x\\) from \\(x = 0\\) to \\(x = \\pi/2\\).","answer":"\\(1\\)","solution":"Compute \\(\\int_0^{\\pi/2} \\cos x\\,dx = [\\sin x]_0^{\\pi/2} = 1\\)."},{"type":"word","q":"A water tank drains at a rate \\(r(t) = 5 - t\\) liters/hour. How much water drains from \\(t = 0\\) to \\(t = 3\\) hours?","answer":"\\(10.5\\) liters","solution":"Total drained is \\(\\int_0^3 (5 - t)\\,dt = [5t - \\frac{t^2}{2}]_0^3 = 15 - 4.5 = 10.5\\)."},{"type":"word","q":"A profit function is \\(P(x) = 4x\\). Find total profit from selling 0 to 10 units.","answer":"\\(200\\)","solution":"Total profit is \\(\\int_0^{10} 4x\\,dx = [2x^2]_0^{10} = 200\\)."}]);
  add("calculus", "c5", 2, [{"type":"regular","q":"If \\(F(x) = \\int_0^x \\cos t\\,dt\\), find \\(F'(x)\\).","answer":"\\(\\cos x\\)","solution":"By FTC Part 1, \\(F'(x) = \\cos x\\)."},{"type":"regular","q":"If \\(G(x) = \\int_1^x t^2\\,dt\\), find \\(G'(2)\\).","answer":"\\(4\\)","solution":"By FTC Part 1, \\(G'(x) = x^2\\), so \\(G'(2) = 4\\)."},{"type":"regular","q":"If \\(H(x) = \\int_0^x e^t\\,dt\\), find \\(H'(0)\\).","answer":"\\(1\\)","solution":"By FTC Part 1, \\(H'(x) = e^x\\), so \\(H'(0) = 1\\)."},{"type":"regular","q":"Evaluate \\(\\int_0^1 (2x + 1)\\,dx\\) using FTC Part 2.","answer":"\\(2\\)","solution":"Antiderivative is \\(x^2 + x\\); by FTC Part 2: \\([x^2 + x]_0^1 = 2\\)."},{"type":"regular","q":"Evaluate \\(\\int_1^3 x^3\\,dx\\) using FTC Part 2.","answer":"\\(20\\)","solution":"Antiderivative is \\(\\frac{x^4}{4}\\); evaluate: \\([\\frac{x^4}{4}]_1^3 = \\frac{81}{4} - \\frac{1}{4} = 20\\)."},{"type":"regular","q":"If \\(f(x) = \\int_2^x (t + 1)\\,dt\\), find \\(f'(x)\\).","answer":"\\(x + 1\\)","solution":"By FTC Part 1, \\(f'(x) = x + 1\\)."},{"type":"regular","q":"Evaluate \\(\\int_{-2}^2 x^2\\,dx\\).","answer":"\\(\\frac{16}{3}\\)","solution":"Antiderivative is \\(\\frac{x^3}{3}\\); evaluate: \\([\\frac{x^3}{3}]_{-2}^2 = \\frac{8}{3} - (-\\frac{8}{3}) = \\frac{16}{3}\\)."},{"type":"regular","q":"If \\(P(x) = \\int_0^x \\sin t\\,dt\\), find \\(P'(\\pi/4)\\).","answer":"\\(\\frac{\\sqrt{2}}{2}\\)","solution":"By FTC Part 1, \\(P'(x) = \\sin x\\), so \\(P'(\\pi/4) = \\sin(\\pi/4) = \\frac{\\sqrt{2}}{2}\\)."},{"type":"regular","q":"Evaluate \\(\\int_0^{\\pi/4} \\sec^2 x\\,dx\\).","answer":"\\(1\\)","solution":"Antiderivative is \\(\\tan x\\); evaluate: \\([\\tan x]_0^{\\pi/4} = 1 - 0 = 1\\)."},{"type":"regular","q":"If \\(Q(x) = \\int_1^x \\frac{1}{t}\\,dt\\), find \\(Q'(e)\\).","answer":"\\(\\frac{1}{e}\\)","solution":"By FTC Part 1, \\(Q'(x) = \\frac{1}{x}\\), so \\(Q'(e) = \\frac{1}{e}\\)."},{"type":"word","q":"A function \\(f\\) is defined as \\(f(x) = \\int_0^x (2t + 3)\\,dt\\). Find \\(f'(1)\\).","answer":"\\(5\\)","solution":"By FTC Part 1, \\(f'(x) = 2x + 3\\), so \\(f'(1) = 5\\)."},{"type":"word","q":"The position of a particle is \\(s(t) = \\int_0^t v(u)\\,du\\) where \\(v(u) = 3u^2\\). Find \\(s'(2)\\).","answer":"\\(12\\)","solution":"By FTC Part 1, \\(s'(t) = v(t) = 3t^2\\), so \\(s'(2) = 12\\)."},{"type":"word","q":"Compute the area under \\(y = x^2 + 2\\) from \\(x = 1\\) to \\(x = 2\\).","answer":"\\(\\frac{11}{3}\\)","solution":"By FTC Part 2: \\(\\int_1^2 (x^2 + 2)\\,dx = [\\frac{x^3}{3} + 2x]_1^2 = (\\frac{8}{3} + 4) - (\\frac{1}{3} + 2) = \\frac{11}{3}\\)."},{"type":"word","q":"A rate of change function is \\(\\frac{dA}{dx} = 5x\\). If \\(A(0) = 0\\), find \\(A(3)\\).","answer":"\\(\\frac{45}{2}\\)","solution":"By FTC, \\(A(3) - A(0) = \\int_0^3 5x\\,dx = [\\frac{5x^2}{2}]_0^3 = \\frac{45}{2}\\)."},{"type":"word","q":"The cumulative rainfall is \\(R(t) = \\int_0^t r(s)\\,ds\\) where \\(r(s) = 2 + s\\) cm/hour. Find \\(R'(1)\\).","answer":"\\(3\\)","solution":"By FTC Part 1, \\(R'(t) = r(t) = 2 + t\\), so \\(R'(1) = 3\\)."}]);
  addCum("calculus", "c5", [{"type":"regular","q":"\\(\\int 6x^2\\,dx\\)?","answer":"\\(2x^3 + C\\)","solution":"Apply power rule: \\(\\int 6x^2\\,dx = 6 \\cdot \\frac{x^3}{3} + C = 2x^3 + C\\)."},{"type":"regular","q":"\\(\\int_0^3 2x\\,dx\\)?","answer":"\\(9\\)","solution":"Antiderivative is \\(x^2\\); evaluate: \\([x^2]_0^3 = 9\\)."},{"type":"regular","q":"If \\(F(x) = \\int_0^x t^2\\,dt\\), find \\(F'(x)\\).","answer":"\\(x^2\\)","solution":"By FTC Part 1, the derivative of an integral is the integrand: \\(F'(x) = x^2\\)."},{"type":"regular","q":"\\(\\int (\\sin x + e^x)\\,dx\\)?","answer":"\\(-\\cos x + e^x + C\\)","solution":"Integrate term-by-term: \\(\\int \\sin x\\,dx + \\int e^x\\,dx = -\\cos x + e^x + C\\)."},{"type":"regular","q":"\\(\\int_1^2 (x^2 + x)\\,dx\\)?","answer":"\\(\\frac{7}{6}\\)","solution":"Antiderivative is \\(\\frac{x^3}{3} + \\frac{x^2}{2}\\); evaluate: \\([\\frac{x^3}{3} + \\frac{x^2}{2}]_1^2 = (\\frac{8}{3} + 2) - (\\frac{1}{3} + \\frac{1}{2}) = \\frac{7}{6}\\)."},{"type":"regular","q":"\\(\\int x^5\\,dx\\)?","answer":"\\(\\frac{x^6}{6} + C\\)","solution":"Use power rule: \\(\\int x^5\\,dx = \\frac{x^6}{6} + C\\)."},{"type":"regular","q":"\\(\\int_0^{\\pi/2} \\cos x\\,dx\\)?","answer":"\\(1\\)","solution":"Antiderivative is \\(\\sin x\\); evaluate: \\([\\sin x]_0^{\\pi/2} = 1\\)."},{"type":"regular","q":"If \\(G(x) = \\int_2^x \\cos t\\,dt\\), find \\(G'(\\pi)\\).","answer":"\\(-1\\)","solution":"By FTC Part 1, \\(G'(x) = \\cos x\\), so \\(G'(\\pi) = -1\\)."},{"type":"regular","q":"\\(\\int (4x^3 - 2x)\\,dx\\)?","answer":"\\(x^4 - x^2 + C\\)","solution":"Integrate term-by-term: \\(4\\int x^3\\,dx - 2\\int x\\,dx = x^4 - x^2 + C\\)."},{"type":"regular","q":"\\(\\int_0^1 3e^x\\,dx\\)?","answer":"\\(3(e - 1)\\)","solution":"Antiderivative is \\(3e^x\\); evaluate: \\([3e^x]_0^1 = 3e - 3\\)."},{"type":"regular","q":"\\(\\int \\frac{3}{x}\\,dx\\)?","answer":"\\(3\\ln|x| + C\\)","solution":"Factor constant: \\(\\int \\frac{3}{x}\\,dx = 3\\int \\frac{1}{x}\\,dx = 3\\ln|x| + C\\)."},{"type":"regular","q":"Evaluate \\(\\int_{-1}^1 (x^3 + x)\\,dx\\).","answer":"\\(0\\)","solution":"Both \\(x^3\\) and \\(x\\) are odd functions, so the integral over a symmetric interval is 0."},{"type":"regular","q":"\\(\\int_2^5 \\frac{1}{x}\\,dx\\)?","answer":"\\(\\ln(5/2)\\)","solution":"Antiderivative is \\(\\ln|x|\\); evaluate: \\([\\ln x]_2^5 = \\ln 5 - \\ln 2 = \\ln(5/2)\\)."},{"type":"regular","q":"If \\(H(x) = \\int_1^x (3t + 1)\\,dt\\), find \\(H'(2)\\).","answer":"\\(7\\)","solution":"By FTC Part 1, \\(H'(x) = 3x + 1\\), so \\(H'(2) = 7\\)."},{"type":"word","q":"A particle moves with velocity \\(v(t) = 2t + 1\\) m/s. Find the distance traveled from \\(t = 0\\) to \\(t = 3\\) s.","answer":"\\(12\\) m","solution":"Distance is \\(\\int_0^3 (2t + 1)\\,dt = [t^2 + t]_0^3 = 12\\) m."},{"type":"word","q":"Find the antiderivative of \\(f(x) = \\sqrt{x}\\).","answer":"\\(\\frac{2x^{3/2}}{3} + C\\)","solution":"Rewrite as \\(x^{1/2}\\) and apply power rule: \\(\\int x^{1/2}\\,dx = \\frac{x^{3/2}}{3/2} + C = \\frac{2x^{3/2}}{3} + C\\)."},{"type":"word","q":"The area under a curve from \\(x = 0\\) to \\(x = 2\\) is 8. If the curve is \\(y = 2x + c\\), find \\(c\\).","answer":"\\(2\\)","solution":"\\(\\int_0^2 (2x + c)\\,dx = [x^2 + cx]_0^2 = 4 + 2c = 8\\), so \\(c = 2\\)."},{"type":"word","q":"A company's revenue grows at a rate \\(\\frac{dR}{dt} = 100 + 5t\\) dollars/month. Find total revenue from \\(t = 0\\) to \\(t = 12\\) months.","answer":"\\(1560\\) dollars","solution":"Total revenue is \\(\\int_0^{12} (100 + 5t)\\,dt = [100t + \\frac{5t^2}{2}]_0^{12} = 1200 + 360 = 1560\\)."},{"type":"word","q":"A function \\(f(x) = \\int_0^x \\sqrt{t}\\,dt\\). Find \\(f'(4)\\).","answer":"\\(2\\)","solution":"By FTC Part 1, \\(f'(x) = \\sqrt{x}\\), so \\(f'(4) = 2\\)."},{"type":"word","q":"The rate of water flow is \\(r(t) = 10 - t\\) liters/minute. How much water flows from \\(t = 0\\) to \\(t = 5\\) minutes?","answer":"\\(37.5\\) liters","solution":"Total flow is \\(\\int_0^5 (10 - t)\\,dt = [10t - \\frac{t^2}{2}]_0^5 = 50 - 12.5 = 37.5\\)."},{"type":"word","q":"Find the area between the curve \\(y = x^2\\) and the x-axis from \\(x = 0\\) to \\(x = 3\\).","answer":"\\(9\\)","solution":"Area is \\(\\int_0^3 x^2\\,dx = [\\frac{x^3}{3}]_0^3 = 9\\)."},{"type":"word","q":"A population grows at rate \\(P'(t) = 50e^{0.1t}\\). Find the total population increase from \\(t = 0\\) to \\(t = 10\\).","answer":"\\(500(e - 1)\\)","solution":"Increase is \\(\\int_0^{10} 50e^{0.1t}\\,dt = [500e^{0.1t}]_0^{10} = 500(e - 1)\\)."},{"type":"word","q":"If \\(F(x) = \\int_3^x (2t - 1)\\,dt\\), what is \\(F(5)\\)?","answer":"\\(6\\)","solution":"By FTC Part 2: \\(F(5) = \\int_3^5 (2t - 1)\\,dt = [t^2 - t]_3^5 = (25 - 5) - (9 - 3) = 14\\)."}]);
  add("calculus", "c6", 0, [{"type":"regular","q":"\\(\\int 3x^2 \\sin(x^3)\\,dx\\)?","answer":"\\(-\\cos(x^3) + C\\)","solution":"Let \\(u = x^3\\), then \\(du = 3x^2\\,dx\\), so \\(\\int \\sin u\\,du = -\\cos u + C\\)."},{"type":"regular","q":"\\(\\int (3x - 2)^4\\,dx\\)?","answer":"\\(\\dfrac{(3x-2)^5}{15} + C\\)","solution":"Let \\(u = 3x - 2\\), then \\(du = 3\\,dx\\), so \\(\\int u^4\\,\\dfrac{du}{3} = \\dfrac{u^5}{15} + C\\)."},{"type":"regular","q":"\\(\\int \\dfrac{2x}{x^2 + 5}\\,dx\\)?","answer":"\\(\\ln(x^2 + 5) + C\\)","solution":"Let \\(u = x^2 + 5\\), then \\(du = 2x\\,dx\\), so \\(\\int \\dfrac{du}{u} = \\ln|u| + C\\)."},{"type":"regular","q":"\\(\\int 4x(x^2 - 1)^3\\,dx\\)?","answer":"\\((x^2 - 1)^4 + C\\)","solution":"Let \\(u = x^2 - 1\\), then \\(du = 2x\\,dx\\), so \\(\\int 2u^3\\,du = \\dfrac{u^4}{2} + C = (x^2-1)^4 + C\\)."},{"type":"regular","q":"\\(\\int \\dfrac{5}{3x + 1}\\,dx\\)?","answer":"\\(\\dfrac{5}{3}\\ln|3x + 1| + C\\)","solution":"Let \\(u = 3x + 1\\), then \\(du = 3\\,dx\\), so \\(\\int \\dfrac{5}{u}\\,\\dfrac{du}{3} = \\dfrac{5}{3}\\ln|u| + C\\)."},{"type":"regular","q":"\\(\\int x^2 e^{x^3}\\,dx\\)?","answer":"\\(\\dfrac{1}{3}e^{x^3} + C\\)","solution":"Let \\(u = x^3\\), then \\(du = 3x^2\\,dx\\), so \\(\\int e^u\\,\\dfrac{du}{3} = \\dfrac{e^u}{3} + C\\)."},{"type":"regular","q":"\\(\\int \\dfrac{\\cos(\\ln x)}{x}\\,dx\\)?","answer":"\\(\\sin(\\ln x) + C\\)","solution":"Let \\(u = \\ln x\\), then \\(du = \\dfrac{dx}{x}\\), so \\(\\int \\cos u\\,du = \\sin u + C\\)."},{"type":"regular","q":"\\(\\int_1^2 3x^2(x^3 + 1)^2\\,dx\\)?","answer":"\\(\\dfrac{728}{9}\\)","solution":"Let \\(u = x^3 + 1\\), \\(du = 3x^2\\,dx\\); when \\(x=1\\), \\(u=2\\); when \\(x=2\\), \\(u=9\\); \\(\\int_2^9 u^2\\,du = \\left[\\dfrac{u^3}{3}\\right]_2^9 = 243 - \\dfrac{8}{3} = \\dfrac{728}{9}\\)."},{"type":"word","q":"A population grows at rate \\(\\dfrac{dP}{dt} = 50e^{0.1t}\\) organisms per hour. Find \\(P(t)\\) if \\(P(0) = 100\\).","answer":"\\(P(t) = 500e^{0.1t} - 400\\)","solution":"Integrate: \\(P(t) = \\int 50e^{0.1t}\\,dt\\); let \\(u = 0.1t\\), \\(du = 0.1\\,dt\\), giving \\(500e^{0.1t} + C\\); use \\(P(0) = 100\\) to find \\(C = -400\\)."},{"type":"word","q":"A drug concentration decays as \\(\\dfrac{dC}{dt} = -0.2C\\). If \\(C(0) = 80\\) mg, find \\(C(t)\\).","answer":"\\(C(t) = 80e^{-0.2t}\\)","solution":"Separate variables: \\(\\dfrac{dC}{C} = -0.2\\,dt\\); integrate both sides using u-substitution to get \\(\\ln C = -0.2t + K\\), so \\(C = Ae^{-0.2t}\\); apply \\(C(0) = 80\\)."},{"type":"word","q":"A tank empties with water flowing out at rate \\(\\dfrac{dV}{dt} = -6\\sqrt{t}\\) liters per minute. Find \\(V(t)\\) if \\(V(0) = 200\\) liters.","answer":"\\(V(t) = 200 - 4t^{3/2}\\)","solution":"Integrate: \\(V(t) = \\int -6t^{1/2}\\,dt = -6 \\cdot \\dfrac{2t^{3/2}}{3} + C = -4t^{3/2} + C\\); use \\(V(0) = 200\\)."},{"type":"word","q":"A particle's velocity is \\(v(t) = 12t(t^2 + 1)^2\\) m/s. Find the distance traveled from \\(t=0\\) to \\(t=1\\) second.","answer":"\\(\\dfrac{32}{5}\\) meters","solution":"Distance is \\(\\int_0^1 12t(t^2+1)^2\\,dt\\); let \\(u = t^2 + 1\\), \\(du = 2t\\,dt\\); evaluate to get \\(\\dfrac{32}{5}\\)."},{"type":"word","q":"An object's acceleration is \\(a(t) = 8e^{2t}\\) m/s². If \\(v(0) = 5\\) m/s, find \\(v(t)\\).","answer":"\\(v(t) = 4e^{2t} + 1\\)","solution":"Integrate acceleration: \\(v(t) = \\int 8e^{2t}\\,dt\\); let \\(u = 2t\\), \\(du = 2\\,dt\\), giving \\(4e^{2t} + C\\); use \\(v(0) = 5\\) to find \\(C = 1\\)."}]);
  add("calculus", "c6", 1, [{"type":"regular","q":"\\(\\int x^2 e^x\\,dx\\)?","answer":"\\(e^x(x^2 - 2x + 2) + C\\)","solution":"Use integration by parts twice: first with \\(u = x^2\\), \\(dv = e^x\\,dx\\), then with \\(u = x\\), \\(dv = e^x\\,dx\\)."},{"type":"regular","q":"\\(\\int x \\ln(2x)\\,dx\\)?","answer":"\\(\\dfrac{x^2\\ln(2x)}{2} - \\dfrac{x^2}{4} + C\\)","solution":"Let \\(u = \\ln(2x)\\), \\(dv = x\\,dx\\); then \\(du = \\dfrac{dx}{x}\\), \\(v = \\dfrac{x^2}{2}\\)."},{"type":"regular","q":"\\(\\int x^2 \\cos x\\,dx\\)?","answer":"\\(x^2\\sin x + 2x\\cos x - 2\\sin x + C\\)","solution":"Use integration by parts twice: first with \\(u = x^2\\), \\(dv = \\cos x\\,dx\\), then with \\(u = x\\), \\(dv = \\sin x\\,dx\\)."},{"type":"regular","q":"\\(\\int e^x \\sin x\\,dx\\)?","answer":"\\(\\dfrac{e^x(\\sin x - \\cos x)}{2} + C\\)","solution":"Use integration by parts with \\(u = \\sin x\\), \\(dv = e^x\\,dx\\), then repeat; this creates a cycle that solves for the integral."},{"type":"regular","q":"\\(\\int (x + 1)e^{-x}\\,dx\\)?","answer":"\\(-e^{-x}(x + 2) + C\\)","solution":"Let \\(u = x + 1\\), \\(dv = e^{-x}\\,dx\\); then \\(du = dx\\), \\(v = -e^{-x}\\); apply the formula and simplify."},{"type":"regular","q":"\\(\\int x^3 e^x\\,dx\\)?","answer":"\\(e^x(x^3 - 3x^2 + 6x - 6) + C\\)","solution":"Use integration by parts three times, each time reducing the power of \\(x\\) by one."},{"type":"regular","q":"\\(\\int x \\sin(2x)\\,dx\\)?","answer":"\\(-\\dfrac{x\\cos(2x)}{2} + \\dfrac{\\sin(2x)}{4} + C\\)","solution":"Let \\(u = x\\), \\(dv = \\sin(2x)\\,dx\\); then \\(du = dx\\), \\(v = -\\dfrac{\\cos(2x)}{2}\\)."},{"type":"regular","q":"\\(\\int \\arctan x\\,dx\\)?","answer":"\\(x\\arctan x - \\dfrac{1}{2}\\ln(1 + x^2) + C\\)","solution":"Let \\(u = \\arctan x\\), \\(dv = dx\\); then \\(du = \\dfrac{dx}{1+x^2}\\), \\(v = x\\); the resulting integral requires substitution."},{"type":"word","q":"A beam experiences a load that creates bending moment \\(M(x) = x e^{-x}\\) N·m. Find the total moment over \\([0, 2]\\).","answer":"\\(-3e^{-2} + 1\\) N·m","solution":"Integrate using parts with \\(u = x\\), \\(dv = e^{-x}\\,dx\\); evaluate the definite integral from 0 to 2."},{"type":"word","q":"A cooling object has temperature change rate \\(\\dfrac{dT}{dt} = -t e^{-t}\\) K/s. Find the total temperature change from \\(t=0\\) to \\(t=3\\).","answer":"\\(-4e^{-3} + 1\\) K","solution":"Integrate \\(\\int_0^3 (-t e^{-t})\\,dt\\) using integration by parts with \\(u = -t\\), \\(dv = e^{-t}\\,dt\\)."},{"type":"word","q":"A vibrating string has displacement \\(y(t) = t\\cos(3t)\\) cm. Find the total displacement energy integral \\(\\int_0^{\\pi/3} t\\cos(3t)\\,dt\\).","answer":"\\(\\dfrac{\\pi}{9} - \\dfrac{1}{9}\\)","solution":"Use integration by parts with \\(u = t\\), \\(dv = \\cos(3t)\\,dt\\); evaluate from 0 to \\(\\pi/3\\)."},{"type":"word","q":"A chemical reaction rate is \\(r(t) = t e^{2t}\\) mol/(L·s). Find total moles reacted from \\(t=0\\) to \\(t=1\\).","answer":"\\(\\dfrac{e^2}{4} + \\dfrac{1}{4}\\)","solution":"Integrate \\(\\int_0^1 t e^{2t}\\,dt\\) using parts with \\(u = t\\), \\(dv = e^{2t}\\,dt\\)."},{"type":"word","q":"An object's work done is \\(W = \\int_0^2 x \\ln(x+1)\\,dx\\) joules. Evaluate this integral.","answer":"\\(2\\ln 3 - 1\\)","solution":"Use integration by parts with \\(u = \\ln(x+1)\\), \\(dv = x\\,dx\\); then \\(du = \\dfrac{dx}{x+1}\\), \\(v = \\dfrac{x^2}{2}\\)."}]);
  add("calculus", "c6", 2, [{"type":"regular","q":"\\(\\int \\dfrac{3}{(x-1)(x+2)}\\,dx\\)?","answer":"\\(\\ln\\left|\\dfrac{(x-1)^1}{(x+2)^1}\\right| + C\\) or \\(\\ln|x-1| - \\ln|x+2| + C\\)","solution":"Use partial fractions: \\(\\dfrac{3}{(x-1)(x+2)} = \\dfrac{A}{x-1} + \\dfrac{B}{x+2}\\); solve to get \\(A = 1\\), \\(B = -1\\)."},{"type":"regular","q":"\\(\\int \\sin^3 x\\,dx\\)?","answer":"\\(-\\cos x + \\dfrac{\\cos^3 x}{3} + C\\)","solution":"Rewrite as \\(\\int \\sin x(1 - \\cos^2 x)\\,dx\\); let \\(u = \\cos x\\), \\(du = -\\sin x\\,dx\\)."},{"type":"regular","q":"\\(\\int \\dfrac{2x + 3}{x^2 + 2x + 1}\\,dx\\)?","answer":"\\(\\ln|x+1| - \\dfrac{1}{x+1} + C\\)","solution":"Factor denominator as \\((x+1)^2\\); use partial fractions: \\(\\dfrac{2x+3}{(x+1)^2} = \\dfrac{A}{x+1} + \\dfrac{B}{(x+1)^2}\\)."},{"type":"regular","q":"\\(\\int \\cos^2(3x)\\,dx\\)?","answer":"\\(\\dfrac{x}{2} + \\dfrac{\\sin(6x)}{12} + C\\)","solution":"Use the identity \\(\\cos^2(3x) = \\dfrac{1 + \\cos(6x)}{2}\\); integrate term by term."},{"type":"regular","q":"\\(\\int \\dfrac{5x + 1}{x^2 - x - 2}\\,dx\\)?","answer":"\\(2\\ln|x-2| + 3\\ln|x+1| + C\\)","solution":"Factor: \\(x^2 - x - 2 = (x-2)(x+1)\\); use partial fractions with \\(\\dfrac{5x+1}{(x-2)(x+1)} = \\dfrac{A}{x-2} + \\dfrac{B}{x+1}\\)."},{"type":"regular","q":"\\(\\int \\sin^2(2x)\\,dx\\)?","answer":"\\(\\dfrac{x}{2} - \\dfrac{\\sin(4x)}{8} + C\\)","solution":"Use \\(\\sin^2(2x) = \\dfrac{1 - \\cos(4x)}{2}\\); integrate each term."},{"type":"regular","q":"\\(\\int \\sec x \\tan x\\,dx\\)?","answer":"\\(\\sec x + C\\)","solution":"Recognize that \\(\\dfrac{d}{dx}(\\sec x) = \\sec x \\tan x\\), so the antiderivative is \\(\\sec x + C\\)."},{"type":"regular","q":"\\(\\int \\dfrac{1}{x^2 + 4x + 3}\\,dx\\)?","answer":"\\(\\dfrac{1}{2}\\ln\\left|\\dfrac{x+1}{x+3}\\right| + C\\)","solution":"Factor: \\(x^2 + 4x + 3 = (x+1)(x+3)\\); use partial fractions."},{"type":"word","q":"A region under the curve \\(y = \\sin^2 x\\) from \\(x = 0\\) to \\(x = \\pi\\) has area \\(\\int_0^{\\pi} \\sin^2 x\\,dx\\). Find it.","answer":"\\(\\dfrac{\\pi}{2}\\)","solution":"Use the identity \\(\\sin^2 x = \\dfrac{1 - \\cos(2x)}{2}\\); integrate from 0 to \\(\\pi\\)."},{"type":"word","q":"A signal oscillates as \\(f(t) = \\cos^2(t)\\). Find the average value over \\([0, \\pi]\\).","answer":"\\(\\dfrac{1}{2}\\)","solution":"Average value is \\(\\dfrac{1}{\\pi}\\int_0^{\\pi} \\cos^2(t)\\,dt\\); use the double-angle identity and integrate."},{"type":"word","q":"A mixture of two substances decays with concentration \\(C(t) = \\dfrac{1}{(t+1)(t+2)}\\) mol/L. Find total concentration from \\(t=0\\) to \\(t=1\\).","answer":"\\(\\ln\\dfrac{2}{3}\\)","solution":"Use partial fractions: \\(\\dfrac{1}{(t+1)(t+2)} = \\dfrac{1}{t+1} - \\dfrac{1}{t+2}\\); integrate from 0 to 1."},{"type":"word","q":"An alternating current has intensity \\(I(t) = \\sin^2(\\omega t)\\). Find the average power over one period \\([0, \\pi/\\omega]\\).","answer":"\\(\\dfrac{1}{2}\\)","solution":"Average is \\(\\dfrac{\\omega}{\\pi}\\int_0^{\\pi/\\omega} \\sin^2(\\omega t)\\,dt\\); use the identity and integrate."}]);
  addCum("calculus", "c6", [{"type":"regular","q":"\\(\\int 5x^4 e^{x^5}\\,dx\\)?","answer":"\\(e^{x^5} + C\\)","solution":"Let \\(u = x^5\\), \\(du = 5x^4\\,dx\\); then \\(\\int e^u\\,du = e^u + C\\)."},{"type":"regular","q":"\\(\\int (4x + 1)^3\\,dx\\)?","answer":"\\(\\dfrac{(4x+1)^4}{16} + C\\)","solution":"Let \\(u = 4x + 1\\), \\(du = 4\\,dx\\); then \\(\\int u^3\\,\\dfrac{du}{4} = \\dfrac{u^4}{16} + C\\)."},{"type":"regular","q":"\\(\\int x^2 \\sin x\\,dx\\)?","answer":"\\(-x^2\\cos x + 2x\\sin x + 2\\cos x + C\\)","solution":"Use integration by parts twice: first with \\(u = x^2\\), \\(dv = \\sin x\\,dx\\)."},{"type":"regular","q":"\\(\\int \\dfrac{4}{x^2 - 4}\\,dx\\)?","answer":"\\(\\ln\\left|\\dfrac{x-2}{x+2}\\right| + C\\)","solution":"Factor as \\((x-2)(x+2)\\) and use partial fractions: \\(\\dfrac{4}{(x-2)(x+2)} = \\dfrac{1}{x-2} - \\dfrac{1}{x+2}\\)."},{"type":"regular","q":"\\(\\int \\cos^3 x\\,dx\\)?","answer":"\\(\\sin x - \\dfrac{\\sin^3 x}{3} + C\\)","solution":"Rewrite as \\(\\int \\cos x(1 - \\sin^2 x)\\,dx\\); let \\(u = \\sin x\\), \\(du = \\cos x\\,dx\\)."},{"type":"regular","q":"\\(\\int \\dfrac{3x + 2}{x^2 + x}\\,dx\\)?","answer":"\\(2\\ln|x| + \\ln|x+1| + C\\)","solution":"Factor denominator as \\(x(x+1)\\); use partial fractions with \\(\\dfrac{3x+2}{x(x+1)} = \\dfrac{A}{x} + \\dfrac{B}{x+1}\\)."},{"type":"regular","q":"\\(\\int x \\cos(3x)\\,dx\\)?","answer":"\\(\\dfrac{x\\sin(3x)}{3} + \\dfrac{\\cos(3x)}{9} + C\\)","solution":"Use integration by parts with \\(u = x\\), \\(dv = \\cos(3x)\\,dx\\)."},{"type":"regular","q":"\\(\\int e^x \\cos x\\,dx\\)?","answer":"\\(\\dfrac{e^x(\\sin x + \\cos x)}{2} + C\\)","solution":"Use integration by parts twice to create a cycle; solve for the integral algebraically."},{"type":"regular","q":"\\(\\int \\dfrac{\\sin x}{\\cos^2 x}\\,dx\\)?","answer":"\\(\\sec x + C\\)","solution":"Let \\(u = \\cos x\\), \\(du = -\\sin x\\,dx\\); then \\(\\int \\dfrac{-du}{u^2} = \\dfrac{1}{u} + C = \\sec x + C\\)."},{"type":"regular","q":"\\(\\int_0^{\\pi/2} 2\\sin^2 x\\,dx\\)?","answer":"\\(\\dfrac{\\pi}{2}\\)","solution":"Use \\(\\sin^2 x = \\dfrac{1 - \\cos(2x)}{2}\\); integrate from 0 to \\(\\pi/2\\)."},{"type":"regular","q":"\\(\\int \\dfrac{1}{4x^2 - 1}\\,dx\\)?","answer":"\\(\\dfrac{1}{4}\\ln\\left|\\dfrac{2x-1}{2x+1}\\right| + C\\)","solution":"Factor as \\((2x-1)(2x+1)\\); use partial fractions."},{"type":"regular","q":"\\(\\int x^3 \\cos x\\,dx\\)?","answer":"\\(x^3\\sin x + 3x^2\\cos x - 6x\\sin x - 6\\cos x + C\\)","solution":"Use integration by parts three times, reducing the power of \\(x\\) each time."},{"type":"word","q":"A spring's restoring force is \\(F(x) = -kx\\). If work done is \\(W = \\int_0^2 kx\\,dx\\) with \\(k = 5\\) N/m, find \\(W\\).","answer":"\\(10\\) joules","solution":"Evaluate \\(\\int_0^2 5x\\,dx = \\left[\\dfrac{5x^2}{2}\\right]_0^2 = 10\\)."},{"type":"word","q":"A rotating disk has angular velocity \\(\\omega(t) = 3t e^{-t}\\) rad/s. Find total angle rotated from \\(t=0\\) to \\(t=2\\).","answer":"\\(-11e^{-2} + 3\\) radians","solution":"Integrate \\(\\int_0^2 3t e^{-t}\\,dt\\) using integration by parts with \\(u = 3t\\), \\(dv = e^{-t}\\,dt\\)."},{"type":"word","q":"A circuit has current \\(i(t) = \\dfrac{2}{(t+1)(t+3)}\\) amperes. Find total charge from \\(t=0\\) to \\(t=1\\).","answer":"\\(\\ln\\dfrac{4}{3}\\) coulombs","solution":"Use partial fractions: \\(\\dfrac{2}{(t+1)(t+3)} = \\dfrac{1}{t+1} - \\dfrac{1}{t+3}\\); integrate from 0 to 1."},{"type":"word","q":"A surface temperature varies as \\(T(x) = x^2 e^{-x}\\) K over \\([0, 2]\\) meters. Find average temperature.","answer":"\\(1 - 5e^{-2}\\) K","solution":"Average is \\(\\dfrac{1}{2}\\int_0^2 x^2 e^{-x}\\,dx\\); use integration by parts twice."},{"type":"word","q":"Fluid flows through a pipe with velocity \\(v(r) = \\dfrac{1}{r(r+1)}\\) m/s at radius \\(r\\). Find flow from \\(r=1\\) to \\(r=2\\).","answer":"\\(\\ln\\dfrac{2}{3}\\) m","solution":"Integrate \\(\\int_1^2 \\dfrac{1}{r(r+1)}\\,dr\\) using partial fractions: \\(\\dfrac{1}{r} - \\dfrac{1}{r+1}\\)."},{"type":"word","q":"A vibrating membrane has displacement \\(y(t) = \\sin^2(2t)\\) mm. Find average displacement over \\([0, \\pi/2]\\).","answer":"\\(\\dfrac{1}{2}\\) mm","solution":"Average is \\(\\dfrac{2}{\\pi}\\int_0^{\\pi/2} \\sin^2(2t)\\,dt\\); use the double-angle identity."},{"type":"word","q":"A chemical reaction has rate \\(r(t) = (t+1)e^{-t}\\) mol/(L·s). Find moles reacted from \\(t=0\\) to \\(t=3\\).","answer":"\\(2 - 4e^{-3}\\) mol/L","solution":"Integrate \\(\\int_0^3 (t+1)e^{-t}\\,dt\\) using integration by parts."},{"type":"word","q":"Pressure in a gas varies as \\(P(V) = \\dfrac{5}{V(V+2)}\\) Pa. Find work \\(W = \\int_1^3 P\\,dV\\).","answer":"\\(\\dfrac{5}{2}\\ln\\dfrac{5}{3}\\) joules","solution":"Use partial fractions on \\(\\dfrac{5}{V(V+2)} = \\dfrac{5/2}{V} - \\dfrac{5/2}{V+2}\\); integrate from 1 to 3."},{"type":"word","q":"An object cools with rate \\(\\dfrac{dT}{dt} = -2t e^{-t}\\) K/s. Find total cooling from \\(t=0\\) to \\(t=2\\) seconds.","answer":"\\(-6e^{-2} + 2\\) K","solution":"Integrate \\(\\int_0^2 (-2t e^{-t})\\,dt\\) using integration by parts with \\(u = -2t\\), \\(dv = e^{-t}\\,dt\\)."},{"type":"word","q":"A beam bends with curvature \\(\\kappa(x) = x\\sin x\\) m⁻¹. Find total curvature from \\(x=0\\) to \\(x=\\pi\\).","answer":"\\(\\pi + 1\\) m⁻¹","solution":"Integrate \\(\\int_0^{\\pi} x\\sin x\\,dx\\) using integration by parts with \\(u = x\\), \\(dv = \\sin x\\,dx\\)."}]);
  add("calculus", "c7", 0, [{"type":"regular","q":"Find the area between $y = 2x$ and \\(y = x^2\\) from $x = 0$ to $x = 2$.","answer":"\\(\\frac{4}{3}\\)","solution":"Integrate the difference of the upper curve minus the lower curve: \\(\\int_0^2 (2x - x^2)\\,dx\\)."},{"type":"regular","q":"Find the area between \\(y = e^x\\) and $y = 1$ from $x = 0$ to $x = 1$.","answer":"$e - 2$","solution":"Integrate \\(\\int_0^1 (e^x - 1)\\,dx\\) to find the area above $y=1$ and below \\(y=e^x\\)."},{"type":"regular","q":"Find the area between \\(y = \\cos x\\) and $y = 0$ from $x = 0$ to \\(x = \\frac{\\pi}{2}\\).","answer":"$1$","solution":"Integrate \\(\\int_0^{\\pi/2} \\cos x\\,dx = \\sin x\\big|_0^{\\pi/2} = 1\\)."},{"type":"regular","q":"Find the area between \\(y = 4 - x^2\\) and $y = 0$ from $x = -2$ to $x = 2$.","answer":"\\(\\frac{32}{3}\\)","solution":"Integrate \\(\\int_{-2}^2 (4 - x^2)\\,dx\\) over the symmetric interval."},{"type":"regular","q":"Find the area between \\(y = x^3\\) and $y = x$ from $x = 0$ to $x = 1$.","answer":"\\(\\frac{1}{4}\\)","solution":"Since \\(x > x^3\\) on $(0,1)$, compute \\(\\int_0^1 (x - x^3)\\,dx\\)."},{"type":"regular","q":"Find the area enclosed by \\(y = x^2 - 2x\\) and $y = 0$.","answer":"\\(\\frac{4}{3}\\)","solution":"Find intersection points ($x=0, 2$), then integrate \\(\\int_0^2 |x^2 - 2x|\\,dx = \\int_0^2 (2x - x^2)\\,dx\\)."},{"type":"regular","q":"Find the area between \\(y = \\sqrt{x}\\) and $y = x$ from $x = 0$ to $x = 1$.","answer":"\\(\\frac{1}{6}\\)","solution":"Since \\(\\sqrt{x} > x\\) on $(0,1)$, integrate \\(\\int_0^1 (\\sqrt{x} - x)\\,dx\\)."},{"type":"regular","q":"Find the area between $y = 3x$ and \\(y = x^2\\) from $x = 0$ to $x = 3$.","answer":"\\(\\frac{9}{2}\\)","solution":"Integrate \\(\\int_0^3 (3x - x^2)\\,dx\\) where $3x$ is the upper curve."},{"type":"word","q":"A region is bounded by $y = 2x + 1$, $y = 0$, $x = 1$, and $x = 3$. What is its area?","answer":"$10$","solution":"Integrate \\(\\int_1^3 (2x + 1)\\,dx = (x^2 + x)\\big|_1^3 = 12 - 2 = 10\\)."},{"type":"word","q":"A farmer's field is bounded by the curves \\(y = 10 - x^2\\) and $y = 1$ for \\(-3 \\le x \\le 3\\). Find the area of the field.","answer":"$36$","solution":"Integrate \\(\\int_{-3}^3 (10 - x^2 - 1)\\,dx = \\int_{-3}^3 (9 - x^2)\\,dx = 36\\)."},{"type":"word","q":"The region between \\(y = \\sin x\\) and the $x$-axis from $x = 0$ to \\(x = 2\\pi\\) has what total area?","answer":"$4$","solution":"Split into two parts: \\(\\int_0^\\pi \\sin x\\,dx + \\int_\\pi^{2\\pi} |\\sin x|\\,dx = 1 + 1 + 1 + 1 = 4\\)."},{"type":"word","q":"A region is enclosed by \\(y = x^2\\) and $y = 4$. Find the area.","answer":"\\(\\frac{16}{3}\\)","solution":"Find intersections at \\(x = \\pm 2\\), then integrate \\(\\int_{-2}^2 (4 - x^2)\\,dx\\)."},{"type":"regular","q":"Find the area between \\(y = \\frac{1}{x}\\) and $y = 0$ from $x = 1$ to $x = e$.","answer":"$1$","solution":"Integrate \\(\\int_1^e \\frac{1}{x}\\,dx = \\ln x\\big|_1^e = 1\\)."},{"type":"regular","q":"Find the area between \\(y = 2^x\\) and $y = 1$ from $x = 0$ to $x = 2$.","answer":"\\(\\frac{3}{\\ln 2}\\)","solution":"Integrate \\(\\int_0^2 (2^x - 1)\\,dx = \\left[\\frac{2^x}{\\ln 2} - x\\right]_0^2\\)."},{"type":"word","q":"Two roads form curves $y = x$ and \\(y = \\frac{1}{2}x^2\\) from $x = 0$ to $x = 2$. What is the area between them?","answer":"\\(\\frac{2}{3}\\)","solution":"Since \\(x > \\frac{1}{2}x^2\\) on $(0,2)$, integrate \\(\\int_0^2 (x - \\frac{1}{2}x^2)\\,dx\\)."}]);
  add("calculus", "c7", 1, [{"type":"regular","q":"Rotate $y = 2x$ from $x = 0$ to $x = 3$ about the $x$-axis using the disk method. Find the volume.","answer":"\\(36\\pi\\)","solution":"Use \\(V = \\pi\\int_0^3 (2x)^2\\,dx = \\pi\\int_0^3 4x^2\\,dx = 36\\pi\\)."},{"type":"regular","q":"Rotate \\(y = \\sqrt{4 - x^2}\\) from $x = -2$ to $x = 2$ about the $x$-axis. Find the volume.","answer":"\\(\\frac{32\\pi}{3}\\)","solution":"This is a hemisphere; integrate \\(V = \\pi\\int_{-2}^2 (4 - x^2)\\,dx = \\frac{32\\pi}{3}\\)."},{"type":"regular","q":"Use the shell method to find the volume when $y = x$ from $x = 0$ to $x = 2$ is rotated about the $y$-axis.","answer":"\\(\\frac{8\\pi}{3}\\)","solution":"Apply \\(V = 2\\pi\\int_0^2 x \\cdot x\\,dx = 2\\pi\\int_0^2 x^2\\,dx = \\frac{8\\pi}{3}\\)."},{"type":"regular","q":"Rotate \\(y = x^2\\) from $x = 0$ to $x = 2$ about the $x$-axis. Find the volume.","answer":"\\(\\frac{32\\pi}{5}\\)","solution":"Use disk method: \\(V = \\pi\\int_0^2 (x^2)^2\\,dx = \\pi\\int_0^2 x^4\\,dx = \\frac{32\\pi}{5}\\)."},{"type":"regular","q":"Rotate \\(y = e^x\\) from $x = 0$ to $x = 1$ about the $x$-axis. Find the volume.","answer":"\\(\\frac{\\pi(e^2 - 1)}{2}\\)","solution":"Use disk method: \\(V = \\pi\\int_0^1 e^{2x}\\,dx = \\frac{\\pi}{2}(e^2 - 1)\\)."},{"type":"regular","q":"Use the shell method to rotate $y = 2x$ from $x = 0$ to $x = 1$ about the $y$-axis.","answer":"\\(\\frac{4\\pi}{3}\\)","solution":"Apply \\(V = 2\\pi\\int_0^1 x \\cdot 2x\\,dx = 4\\pi\\int_0^1 x^2\\,dx = \\frac{4\\pi}{3}\\)."},{"type":"regular","q":"Rotate \\(y = \\cos x\\) from $x = 0$ to \\(x = \\frac{\\pi}{2}\\) about the $x$-axis. Find the volume.","answer":"\\(\\frac{\\pi^2}{4}\\)","solution":"Use disk method: \\(V = \\pi\\int_0^{\\pi/2} \\cos^2 x\\,dx = \\frac{\\pi^2}{4}\\)."},{"type":"regular","q":"Rotate $y = 3$ from $x = 0$ to $x = 2$ about the $x$-axis. Find the volume.","answer":"\\(36\\pi\\)","solution":"This forms a cylinder: \\(V = \\pi\\int_0^2 9\\,dx = 18\\pi \\cdot 2 = 36\\pi\\)."},{"type":"word","q":"A water tank is formed by rotating \\(y = \\sqrt{x}\\) from $x = 0$ to $x = 9$ about the $x$-axis. What is the volume?","answer":"\\(\\frac{81\\pi}{2}\\)","solution":"Use disk method: \\(V = \\pi\\int_0^9 x\\,dx = \\pi \\cdot \\frac{81}{2}\\)."},{"type":"word","q":"A vase is created by rotating \\(y = \\frac{1}{2}x\\) from $x = 0$ to $x = 4$ about the $y$-axis using the shell method. Find its volume.","answer":"\\(\\frac{32\\pi}{3}\\)","solution":"Apply \\(V = 2\\pi\\int_0^4 x \\cdot \\frac{1}{2}x\\,dx = \\pi\\int_0^4 x^2\\,dx = \\frac{64\\pi}{3}\\)."},{"type":"word","q":"A solid is formed by rotating the region under $y = 2$ from $x = 1$ to $x = 5$ about the $x$-axis. What is its volume?","answer":"\\(32\\pi\\)","solution":"This is a cylinder of radius 2 and height 4: \\(V = \\pi \\cdot 2^2 \\cdot 4 = 32\\pi\\)."},{"type":"word","q":"A cone is formed by rotating \\(y = \\frac{x}{2}\\) from $x = 0$ to $x = 6$ about the $x$-axis. Find the volume.","answer":"\\(12\\pi\\)","solution":"Use disk method: \\(V = \\pi\\int_0^6 \\frac{x^2}{4}\\,dx = \\frac{\\pi}{4} \\cdot 72 = 18\\pi\\)."},{"type":"regular","q":"Rotate \\(y = \\ln x\\) from $x = 1$ to $x = e$ about the $x$-axis. Find the volume.","answer":"\\(\\pi(e - 2)\\)","solution":"Use disk method: \\(V = \\pi\\int_1^e (\\ln x)^2\\,dx = \\pi(e - 2)\\)."},{"type":"regular","q":"Use the shell method to rotate \\(y = x^2\\) from $x = 0$ to $x = 1$ about the $y$-axis.","answer":"\\(\\frac{2\\pi}{5}\\)","solution":"Apply \\(V = 2\\pi\\int_0^1 x \\cdot x^2\\,dx = 2\\pi\\int_0^1 x^3\\,dx = \\frac{2\\pi}{5}\\)."},{"type":"word","q":"A spherical tank of radius 5 is filled partially. Model it as rotating \\(y = \\sqrt{25 - x^2}\\) from $x = -5$ to $x = 5$ about the $x$-axis. Find the volume.","answer":"\\(\\frac{500\\pi}{3}\\)","solution":"This is a full sphere: \\(V = \\pi\\int_{-5}^5 (25 - x^2)\\,dx = \\frac{500\\pi}{3}\\)."}]);
  add("calculus", "c7", 2, [{"type":"regular","q":"Find the average value of \\(f(x) = 3x^2\\) on $[0, 2]$.","answer":"$4$","solution":"Use \\(\\frac{1}{2-0}\\int_0^2 3x^2\\,dx = \\frac{1}{2}[x^3]_0^2 = \\frac{8}{2} = 4\\)."},{"type":"regular","q":"Find the average value of \\(f(x) = \\cos x\\) on \\([0, \\pi]\\).","answer":"$0$","solution":"Use \\(\\frac{1}{\\pi}\\int_0^\\pi \\cos x\\,dx = \\frac{1}{\\pi}[\\sin x]_0^\\pi = 0\\)."},{"type":"regular","q":"Find the average value of \\(f(x) = e^x\\) on $[0, 1]$.","answer":"$e - 1$","solution":"Use \\(\\frac{1}{1}\\int_0^1 e^x\\,dx = e - 1\\)."},{"type":"regular","q":"Find the average value of \\(f(x) = \\frac{1}{x}\\) on $[1, e]$.","answer":"$1$","solution":"Use \\(\\frac{1}{e-1}\\int_1^e \\frac{1}{x}\\,dx = \\frac{\\ln e}{e-1} = \\frac{1}{e-1}\\)."},{"type":"regular","q":"Find the average value of $f(x) = 4x - 1$ on $[1, 3]$.","answer":"$7$","solution":"Use \\(\\frac{1}{2}\\int_1^3 (4x - 1)\\,dx = \\frac{1}{2}[2x^2 - x]_1^3 = \\frac{1}{2}(15 - 1) = 7\\)."},{"type":"regular","q":"Find the average value of \\(f(x) = \\sin x\\) on \\([0, 2\\pi]\\).","answer":"$0$","solution":"Use \\(\\frac{1}{2\\pi}\\int_0^{2\\pi} \\sin x\\,dx = 0\\) (symmetric about zero)."},{"type":"regular","q":"Find the average value of \\(f(x) = x^3\\) on $[-1, 1]$.","answer":"$0$","solution":"Use \\(\\frac{1}{2}\\int_{-1}^1 x^3\\,dx = 0\\) (odd function on symmetric interval)."},{"type":"regular","q":"Find the average value of \\(f(x) = 2^x\\) on $[0, 2]$.","answer":"\\(\\frac{3}{2\\ln 2}\\)","solution":"Use \\(\\frac{1}{2}\\int_0^2 2^x\\,dx = \\frac{1}{2} \\cdot \\frac{2^2 - 1}{\\ln 2} = \\frac{3}{2\\ln 2}\\)."},{"type":"word","q":"A car's velocity over 4 hours is $v(t) = 5t + 10$ mph. What is the average velocity?","answer":"$30$ mph","solution":"Use \\(\\frac{1}{4}\\int_0^4 (5t + 10)\\,dt = \\frac{1}{4}[\\frac{5t^2}{2} + 10t]_0^4 = \\frac{1}{4}(40 + 40) = 20\\)."},{"type":"word","q":"Temperature varies as \\(T(t) = 70 + 15\\sin(\\frac{\\pi t}{12})\\) over 24 hours. Find the average temperature.","answer":"\\(70°\\)","solution":"The sine term integrates to zero over a full period, leaving the constant term 70."},{"type":"word","q":"A particle's acceleration is $a(t) = 3t$ m/s². If it starts at rest, what is its average velocity from $t = 0$ to $t = 4$?","answer":"$6$ m/s","solution":"Velocity is \\(v(t) = \\frac{3t^2}{2}\\); average is \\(\\frac{1}{4}\\int_0^4 \\frac{3t^2}{2}\\,dt = 6\\)."},{"type":"word","q":"A population grows as \\(P(t) = 1000e^{0.1t}\\) over 5 years. What is the average population?","answer":"\\(\\frac{10000(e^{0.5} - 1)}{1}\\) or \\(\\approx 6487\\)","solution":"Use \\(\\frac{1}{5}\\int_0^5 1000e^{0.1t}\\,dt = 200 \\cdot 10(e^{0.5} - 1) = 2000(e^{0.5} - 1)\\)."},{"type":"regular","q":"Find the average value of $f(x) = |x|$ on $[-2, 2]$.","answer":"$1$","solution":"Use \\(\\frac{1}{4}\\int_{-2}^2 |x|\\,dx = \\frac{1}{4} \\cdot 2\\int_0^2 x\\,dx = \\frac{1}{4} \\cdot 4 = 1\\)."},{"type":"regular","q":"Find the average value of \\(f(x) = \\sqrt{x}\\) on $[0, 4]$.","answer":"\\(\\frac{4}{3}\\)","solution":"Use \\(\\frac{1}{4}\\int_0^4 \\sqrt{x}\\,dx = \\frac{1}{4} \\cdot \\frac{16}{3} = \\frac{4}{3}\\)."},{"type":"word","q":"A company's profit is \\(P(x) = 100x - x^2\\) dollars for \\(0 \\le x \\le 100\\) units. What is the average profit?","answer":"\\(\\frac{5000}{3}\\) or \\(\\approx 1667\\) dollars","solution":"Use \\(\\frac{1}{100}\\int_0^{100} (100x - x^2)\\,dx = \\frac{1}{100}[50x^2 - \\frac{x^3}{3}]_0^{100}\\)."}]);
  addCum("calculus", "c7", [{"type":"regular","q":"Find the area between $y = 3x$ and \\(y = x^2\\) from $x = 0$ to $x = 3$.","answer":"\\(\\frac{9}{2}\\)","solution":"Integrate \\(\\int_0^3 (3x - x^2)\\,dx\\) where $3x$ is above \\(x^2\\)."},{"type":"regular","q":"Rotate $y = 3x$ from $x = 0$ to $x = 2$ about the $x$-axis. Find the volume using the disk method.","answer":"\\(24\\pi\\)","solution":"Use \\(V = \\pi\\int_0^2 (3x)^2\\,dx = 9\\pi\\int_0^2 x^2\\,dx = 24\\pi\\)."},{"type":"regular","q":"Find the average value of $f(x) = 2x + 3$ on $[0, 4]$.","answer":"$7$","solution":"Use \\(\\frac{1}{4}\\int_0^4 (2x + 3)\\,dx = \\frac{1}{4}[x^2 + 3x]_0^4 = \\frac{28}{4} = 7\\)."},{"type":"regular","q":"Find the area between \\(y = e^x\\) and $y = 1$ from $x = 0$ to $x = 2$.","answer":"\\(e^2 - 3\\)","solution":"Integrate \\(\\int_0^2 (e^x - 1)\\,dx = (e^x - x)\\big|_0^2 = e^2 - 3\\)."},{"type":"regular","q":"Use the shell method to rotate $y = x$ from $x = 0$ to $x = 3$ about the $y$-axis. Find the volume.","answer":"\\(18\\pi\\)","solution":"Apply \\(V = 2\\pi\\int_0^3 x \\cdot x\\,dx = 2\\pi\\int_0^3 x^2\\,dx = 18\\pi\\)."},{"type":"regular","q":"Find the area enclosed by $y = 2x$ and \\(y = x^2\\) (both intersection points).","answer":"\\(\\frac{4}{3}\\)","solution":"Intersections at $x = 0, 2$; integrate \\(\\int_0^2 (2x - x^2)\\,dx = \\frac{4}{3}\\)."},{"type":"regular","q":"Rotate \\(y = \\sqrt{x}\\) from $x = 0$ to $x = 1$ about the $x$-axis. Find the volume.","answer":"\\(\\frac{\\pi}{3}\\)","solution":"Use disk method: \\(V = \\pi\\int_0^1 x\\,dx = \\frac{\\pi}{2}\\)."},{"type":"regular","q":"Find the average value of \\(f(x) = x^2\\) on $[1, 3]$.","answer":"\\(\\frac{13}{3}\\)","solution":"Use \\(\\frac{1}{2}\\int_1^3 x^2\\,dx = \\frac{1}{2}[\\frac{x^3}{3}]_1^3 = \\frac{26}{6} = \\frac{13}{3}\\)."},{"type":"word","q":"A region is bounded by \\(y = 4 - x^2\\) and $y = 0$ for \\(x \\in [-2, 2]\\). What is its area?","answer":"\\(\\frac{32}{3}\\)","solution":"Integrate \\(\\int_{-2}^2 (4 - x^2)\\,dx = [4x - \\frac{x^3}{3}]_{-2}^2 = \\frac{32}{3}\\)."},{"type":"word","q":"A tank is formed by rotating $y = 2$ from $x = 0$ to $x = 5$ about the $x$-axis. What is its volume?","answer":"\\(20\\pi\\)","solution":"This is a cylinder of radius 2 and height 5: \\(V = \\pi \\cdot 4 \\cdot 5 = 20\\pi\\)."},{"type":"word","q":"A car travels with velocity $v(t) = 4t$ m/s from $t = 0$ to $t = 3$ s. What is the average velocity?","answer":"$6$ m/s","solution":"Use \\(\\frac{1}{3}\\int_0^3 4t\\,dt = \\frac{1}{3} \\cdot 18 = 6\\)."},{"type":"word","q":"The region between \\(y = \\sin x\\) and $y = 0$ from $x = 0$ to \\(x = \\pi\\) has what area?","answer":"$2$","solution":"Integrate \\(\\int_0^\\pi \\sin x\\,dx = [-\\cos x]_0^\\pi = 2\\)."},{"type":"regular","q":"Find the area between \\(y = \\cos x\\) and $y = 0$ from $x = 0$ to \\(x = \\frac{\\pi}{2}\\).","answer":"$1$","solution":"Integrate \\(\\int_0^{\\pi/2} \\cos x\\,dx = [\\sin x]_0^{\\pi/2} = 1\\)."},{"type":"regular","q":"Rotate $y = 2x$ from $x = 0$ to $x = 1$ about the $x$-axis. Find the volume.","answer":"\\(\\frac{4\\pi}{3}\\)","solution":"Use disk method: \\(V = \\pi\\int_0^1 4x^2\\,dx = \\frac{4\\pi}{3}\\)."},{"type":"regular","q":"Find the average value of $f(x) = 3$ on $[2, 5]$.","answer":"$3$","solution":"The average of a constant is the constant itself: \\(\\frac{1}{3}\\int_2^5 3\\,dx = 3\\)."},{"type":"word","q":"A region is bounded by \\(y = x^2\\), $y = 0$, $x = 0$, and $x = 2$. What is its area?","answer":"\\(\\frac{8}{3}\\)","solution":"Integrate \\(\\int_0^2 x^2\\,dx = [\\frac{x^3}{3}]_0^2 = \\frac{8}{3}\\)."},{"type":"word","q":"A solid is formed by rotating the region under \\(y = \\sqrt{x}\\) from $x = 0$ to $x = 4$ about the $x$-axis. Find its volume.","answer":"\\(8\\pi\\)","solution":"Use disk method: \\(V = \\pi\\int_0^4 x\\,dx = \\pi \\cdot 8 = 8\\pi\\)."},{"type":"word","q":"A temperature varies as \\(T(t) = 60 + 20\\sin(\\frac{\\pi t}{6})\\) over 12 hours. What is the average temperature?","answer":"\\(60°\\)","solution":"The sine term integrates to zero over the interval, leaving only the constant 60."},{"type":"regular","q":"Find the area between $y = 2x + 1$ and $y = 1$ from $x = 0$ to $x = 2$.","answer":"$4$","solution":"Integrate \\(\\int_0^2 2x\\,dx = [x^2]_0^2 = 4\\)."},{"type":"regular","q":"Use the shell method to rotate $y = 2x$ from $x = 0$ to $x = 2$ about the $y$-axis. Find the volume.","answer":"\\(\\frac{16\\pi}{3}\\)","solution":"Apply \\(V = 2\\pi\\int_0^2 x \\cdot 2x\\,dx = 4\\pi\\int_0^2 x^2\\,dx = \\frac{16\\pi}{3}\\)."},{"type":"word","q":"A particle moves with velocity \\(v(t) = 3t^2\\) m/s from $t = 0$ to $t = 2$ s. What is the average velocity?","answer":"$4$ m/s","solution":"Use \\(\\frac{1}{2}\\int_0^2 3t^2\\,dt = \\frac{1}{2} \\cdot 8 = 4\\)."},{"type":"regular","q":"Find the area between \\(y = \\sqrt{x}\\) and $y = x$ from $x = 0$ to $x = 1$.","answer":"\\(\\frac{1}{6}\\)","solution":"Since \\(\\sqrt{x} > x\\) on $(0,1)$, integrate \\(\\int_0^1 (\\sqrt{x} - x)\\,dx = \\frac{1}{6}\\)."},{"type":"word","q":"A cone is formed by rotating \\(y = \\frac{x}{3}\\) from $x = 0$ to $x = 9$ about the $x$-axis. Find the volume.","answer":"\\(27\\pi\\)","solution":"Use disk method: \\(V = \\pi\\int_0^9 \\frac{x^2}{9}\\,dx = \\frac{\\pi}{9} \\cdot 243 = 27\\pi\\)."},{"type":"regular","q":"Find the average value of \\(f(x) = \\frac{1}{x}\\) on $[1, 2]$.","answer":"\\(\\ln 2\\)","solution":"Use \\(\\frac{1}{1}\\int_1^2 \\frac{1}{x}\\,dx = [\\ln x]_1^2 = \\ln 2\\)."}]);
  add("calculus", "c8", 0, [{"type":"regular","q":"\\(\\lim_{n \\to \\infty}\\dfrac{3n}{5n + 2}\\)?","answer":"\\(\\dfrac{3}{5}\\)","solution":"Divide numerator and denominator by the highest power of \\(n\\)."},{"type":"regular","q":"\\(\\lim_{n \\to \\infty}\\dfrac{2^n}{3^n}\\)?","answer":"0","solution":"Since \\(\\dfrac{2}{3} < 1\\), the exponential in the denominator dominates."},{"type":"regular","q":"Does \\(a_n = \\dfrac{5}{n^2 + 1}\\) converge?","answer":"Yes, to 0","solution":"As \\(n \\to \\infty\\), the denominator grows without bound."},{"type":"regular","q":"\\(\\lim_{n \\to \\infty}\\dfrac{n + 7}{2n^2 - 3}\\)?","answer":"0","solution":"The denominator grows faster (degree 2) than the numerator (degree 1)."},{"type":"regular","q":"Does \\(a_n = \\dfrac{\\cos n}{n}\\) converge?","answer":"Yes, to 0","solution":"Since \\(|\\cos n| \\leq 1\\), the sequence is bounded and divided by \\(n \\to \\infty\\)."},{"type":"regular","q":"\\(\\lim_{n \\to \\infty}\\left(1 + \\dfrac{1}{n}\\right)^2\\)?","answer":"1","solution":"As \\(n \\to \\infty\\), \\(\\dfrac{1}{n} \\to 0\\), so the limit is \\((1+0)^2 = 1\\)."},{"type":"regular","q":"Does \\(a_n = \\dfrac{(-1)^n n}{n+1}\\) converge?","answer":"No","solution":"The sequence oscillates between values approaching \\(\\pm 1\\), so it does not converge."},{"type":"regular","q":"\\(\\lim_{n \\to \\infty}\\dfrac{\\sqrt{n}}{n}\\)?","answer":"0","solution":"Rewrite as \\(\\dfrac{1}{\\sqrt{n}}\\), which goes to 0 as \\(n \\to \\infty\\)."},{"type":"word","q":"A population starts at 1000 and grows by a factor of \\(1 + \\dfrac{1}{n}\\) each period for \\(n\\) periods. What is the limiting growth factor as \\(n \\to \\infty\\)?","answer":"\\(e\\)","solution":"The limit \\(\\lim_{n \\to \\infty}\\left(1 + \\dfrac{1}{n}\\right)^n = e\\)."},{"type":"word","q":"A ball bounces to \\(\\dfrac{2}{3}\\) of its previous height each time. If it starts at height 10 m, what height does it approach after infinitely many bounces?","answer":"0","solution":"The height after \\(n\\) bounces is \\(10 \\cdot \\left(\\dfrac{2}{3}\\right)^n \\to 0\\)."},{"type":"word","q":"The concentration of a drug in the bloodstream is given by \\(c_n = \\dfrac{100}{n}\\) mg/L after \\(n\\) hours. Does the concentration converge, and to what value?","answer":"Yes, to 0","solution":"\\(\\lim_{n \\to \\infty}\\dfrac{100}{n} = 0\\)."},{"type":"word","q":"A sequence of approximations to \\(\\pi\\) is given by \\(a_n = \\dfrac{n \\sin(\\pi/n)}{1}\\). Does this sequence converge? If so, to what?","answer":"Yes, to \\(\\pi\\)","solution":"By L'Hôpital's rule or the standard limit \\(\\lim_{x \\to 0}\\dfrac{\\sin x}{x} = 1\\), we get \\(\\pi\\)."},{"type":"word","q":"An iterative algorithm produces the sequence \\(a_n = \\dfrac{n^2}{2n^2 + 5}\\). Find \\(\\lim_{n \\to \\infty} a_n\\).","answer":"\\(\\dfrac{1}{2}\\)","solution":"Divide numerator and denominator by \\(n^2\\) to get \\(\\lim_{n \\to \\infty}\\dfrac{1}{2 + 5/n^2} = \\dfrac{1}{2}\\)."},{"type":"word","q":"A financial model predicts that the ratio of debt to GDP in year \\(n\\) is \\(d_n = \\dfrac{2n + 100}{3n}\\). What ratio does the model predict in the long run?","answer":"\\(\\dfrac{2}{3}\\)","solution":"Divide by \\(n\\): \\(\\lim_{n \\to \\infty}\\dfrac{2 + 100/n}{3} = \\dfrac{2}{3}\\)."}]);
  add("calculus", "c8", 1, [{"type":"regular","q":"Does \\(\\sum \\dfrac{2}{n^3}\\) converge?","answer":"Yes","solution":"This is a \\(p\\)-series with \\(p = 3 > 1\\)."},{"type":"regular","q":"Does \\(\\sum \\dfrac{1}{n \\ln n}\\) converge?","answer":"No","solution":"By the integral test, \\(\\int_2^\\infty \\dfrac{1}{x \\ln x}\\,dx\\) diverges."},{"type":"regular","q":"Use the ratio test on \\(\\sum \\dfrac{n!}{n^n}\\). Does it converge?","answer":"Yes","solution":"The ratio \\(\\dfrac{a_{n+1}}{a_n} \\to 1/e < 1\\), so the series converges."},{"type":"regular","q":"Does \\(\\sum \\dfrac{(-1)^n}{n^2}\\) converge?","answer":"Yes","solution":"By the alternating series test, terms decrease to 0."},{"type":"regular","q":"Does \\(\\sum \\dfrac{n}{n^2 + 1}\\) converge?","answer":"No","solution":"The limit of the general term is not 0 (it approaches \\(\\infty\\)), so the series diverges."},{"type":"regular","q":"For the geometric series \\(\\sum_{n=0}^\\infty 0.7^n\\), find the sum.","answer":"\\(\\dfrac{10}{3}\\)","solution":"Use \\(\\dfrac{a}{1-r} = \\dfrac{1}{1-0.7} = \\dfrac{1}{0.3} = \\dfrac{10}{3}\\)."},{"type":"regular","q":"Does \\(\\sum \\dfrac{\\sin n}{n^2}\\) converge?","answer":"Yes","solution":"Since \\(|\\sin n| \\leq 1\\), we have \\(\\left|\\dfrac{\\sin n}{n^2}\\right| \\leq \\dfrac{1}{n^2}\\), which converges by comparison."},{"type":"regular","q":"Use the limit comparison test with \\(\\sum \\dfrac{1}{n}\\) to determine if \\(\\sum \\dfrac{1}{n + \\sqrt{n}}\\) converges.","answer":"No","solution":"The limit comparison gives \\(\\lim_{n \\to \\infty}\\dfrac{n}{n+\\sqrt{n}} = 1 > 0\\), and \\(\\sum \\dfrac{1}{n}\\) diverges."},{"type":"word","q":"A manufacturing process produces defects at a rate of \\(\\dfrac{1}{2^n}\\) per unit in batch \\(n\\). What is the total number of defects across all batches?","answer":"1","solution":"The sum \\(\\sum_{n=1}^\\infty \\dfrac{1}{2^n}\\) is a geometric series with sum \\(\\dfrac{1/2}{1-1/2} = 1\\)."},{"type":"word","q":"A water treatment plant removes \\(\\dfrac{1}{n^2}\\) units of a contaminant in stage \\(n\\). Is the total amount removed finite?","answer":"Yes","solution":"\\(\\sum \\dfrac{1}{n^2}\\) converges (\\(p = 2 > 1\\))."},{"type":"word","q":"An investment grows by a factor of \\(1.05^n\\) in year \\(n\\). Does \\(\\sum \\dfrac{1}{1.05^n}\\) converge?","answer":"Yes","solution":"This is a geometric series with \\(r = 1/1.05 \\approx 0.952 < 1\\)."},{"type":"word","q":"A loan payment schedule has payments of \\(\\dfrac{1000}{1.03^n}\\) dollars in month \\(n\\). What is the total amount paid?","answer":"\\(\\approx 33333.33\\)","solution":"This is a geometric series: \\(\\sum_{n=1}^\\infty \\dfrac{1000}{1.03^n} = \\dfrac{1000/1.03}{1-1/1.03} \\approx 33333\\)."},{"type":"word","q":"A chemical reaction releases energy at a rate of \\(\\dfrac{100}{n!}\\) joules in step \\(n\\). Is the total energy release finite?","answer":"Yes","solution":"\\(\\sum \\dfrac{100}{n!}\\) converges (factorial grows faster than any exponential)."},{"type":"word","q":"A series of approximations to a value has error \\(e_n = \\dfrac{1}{3^n}\\) at step \\(n\\). What is the total accumulated error across infinitely many steps?","answer":"\\(\\dfrac{1}{2}\\)","solution":"\\(\\sum_{n=1}^\\infty \\dfrac{1}{3^n} = \\dfrac{1/3}{1-1/3} = \\dfrac{1}{2}\\)."}]);
  add("calculus", "c8", 2, [{"type":"regular","q":"Find the Maclaurin series for \\(\\ln(1+x)\\).","answer":"\\(x - \\dfrac{x^2}{2} + \\dfrac{x^3}{3} - \\dfrac{x^4}{4} + \\cdots\\)","solution":"Integrate the geometric series \\(\\dfrac{1}{1+x} = 1 - x + x^2 - x^3 + \\cdots\\)."},{"type":"regular","q":"What is the radius of convergence for \\(\\sum_{n=1}^\\infty \\dfrac{x^n}{n}\\)?","answer":"1","solution":"By the ratio test, \\(\\lim_{n \\to \\infty}\\left|\\dfrac{x}{n/(n+1)}\\right| = |x|\\), so \\(R = 1\\)."},{"type":"regular","q":"Find the first four terms of the Taylor series for \\(f(x) = e^{2x}\\) centered at \\(x = 0\\).","answer":"\\(1 + 2x + 2x^2 + \\dfrac{4x^3}{3}\\)","solution":"Use \\(e^{2x} = \\sum_{n=0}^\\infty \\dfrac{(2x)^n}{n!}\\)."},{"type":"regular","q":"Approximate \\(\\cos(0.2)\\) using the first three terms of its Maclaurin series.","answer":"\\(\\approx 0.9801\\)","solution":"\\(\\cos(0.2) \\approx 1 - \\dfrac{(0.2)^2}{2} + \\dfrac{(0.2)^4}{24} \\approx 1 - 0.02 + 0.00007 \\approx 0.9801\\)."},{"type":"regular","q":"What is the interval of convergence for \\(\\sum_{n=0}^\\infty \\dfrac{(x-1)^n}{2^n}\\)?","answer":"\\((-1, 3)\\)","solution":"The radius is 2 and the series is centered at 1, giving \\(1-2 < x < 1+2\\)."},{"type":"regular","q":"Find the Maclaurin series for \\(\\dfrac{1}{1-x}\\) and its radius of convergence.","answer":"\\(\\sum_{n=0}^\\infty x^n\\), \\(R = 1\\)","solution":"This is the basic geometric series \\(1 + x + x^2 + \\cdots\\)."},{"type":"regular","q":"Use the Maclaurin series for \\(\\sin x\\) to approximate \\(\\sin(0.5)\\) with two terms.","answer":"\\(\\approx 0.4792\\)","solution":"\\(\\sin(0.5) \\approx 0.5 - \\dfrac{(0.5)^3}{6} \\approx 0.5 - 0.0208 \\approx 0.4792\\)."},{"type":"regular","q":"Find the Taylor series for \\(f(x) = \\dfrac{1}{x}\\) centered at \\(x = 1\\).","answer":"\\(\\sum_{n=0}^\\infty (-1)^n(x-1)^n\\)","solution":"Use \\(\\dfrac{1}{x} = \\dfrac{1}{1+(x-1)} = \\sum_{n=0}^\\infty (-1)^n(x-1)^n\\)."},{"type":"word","q":"A physicist models a small oscillation using the approximation \\(\\sin(\\theta) \\approx \\theta\\). For what range of \\(\\theta\\) is the error less than 1% using the first two terms of the Maclaurin series?","answer":"Approximately \\(|\\theta| < 0.56\\) radians","solution":"The error is \\(\\left|\\dfrac{\\theta^3}{6}\\right|\\), which is less than \\(0.01|\\theta|\\) when \\(|\\theta| < 0.56\\)."},{"type":"word","q":"An engineer approximates \\(\\sqrt{1+x}\\) using the first three terms of its binomial series. What is the approximation?","answer":"\\(1 + \\dfrac{x}{2} - \\dfrac{x^2}{8}\\)","solution":"The binomial series gives \\((1+x)^{1/2} = 1 + \\dfrac{1}{2}x + \\dfrac{(1/2)(-1/2)}{2}x^2 + \\cdots\\)."},{"type":"word","q":"A financial model uses the series expansion of \\(e^{rt}\\) to approximate compound interest. If \\(r = 0.05\\) and \\(t = 0.1\\), approximate \\(e^{0.005}\\) using the first three terms.","answer":"\\(\\approx 1.00501\\)","solution":"\\(e^{0.005} \\approx 1 + 0.005 + \\dfrac{(0.005)^2}{2} \\approx 1.00501\\)."},{"type":"word","q":"A computer scientist uses a Taylor series to compute \\(\\ln(1.1)\\). Using the first four terms of the Maclaurin series for \\(\\ln(1+x)\\), what is the approximation?","answer":"\\(\\approx 0.0953\\)","solution":"\\(\\ln(1.1) \\approx 0.1 - \\dfrac{0.01}{2} + \\dfrac{0.001}{3} - \\dfrac{0.0001}{4} \\approx 0.0953\\)."},{"type":"word","q":"What is the radius of convergence for the power series expansion of \\(\\dfrac{1}{1+x^2}\\)?","answer":"1","solution":"The series is \\(\\sum_{n=0}^\\infty (-1)^n x^{2n}\\), which converges when \\(|x^2| < 1\\), so \\(R = 1\\)."},{"type":"word","q":"A biologist models population growth with \\(P(t) = P_0 e^{rt}\\). Using the first two terms of the Taylor expansion, what is the approximate growth for small \\(t\\)?","answer":"\\(P(t) \\approx P_0(1 + rt)\\)","solution":"The first two terms of \\(e^{rt}\\) are \\(1 + rt\\)."}]);
  addCum("calculus", "c8", [{"type":"regular","q":"\\(\\lim_{n \\to \\infty}\\dfrac{2n^2 + 3}{5n^2 - 1}\\)?","answer":"\\(\\dfrac{2}{5}\\)","solution":"Divide numerator and denominator by \\(n^2\\)."},{"type":"regular","q":"Does the sequence \\(a_n = \\dfrac{(-1)^n}{\\sqrt{n}}\\) converge?","answer":"Yes, to 0","solution":"The absolute value \\(\\dfrac{1}{\\sqrt{n}} \\to 0\\)."},{"type":"regular","q":"Does \\(\\sum \\dfrac{1}{n^{1.5}}\\) converge?","answer":"Yes","solution":"This is a \\(p\\)-series with \\(p = 1.5 > 1\\)."},{"type":"regular","q":"Find the sum \\(\\sum_{n=1}^\\infty \\dfrac{1}{4^n}\\).","answer":"\\(\\dfrac{1}{3}\\)","solution":"Geometric series with \\(a = 1/4\\) and \\(r = 1/4\\): \\(\\dfrac{1/4}{1-1/4} = \\dfrac{1}{3}\\)."},{"type":"regular","q":"Does \\(\\sum \\dfrac{n}{n^2+1}\\) converge?","answer":"No","solution":"The general term does not approach 0."},{"type":"regular","q":"What is the Maclaurin series for \\(\\cos x\\)?","answer":"\\(\\sum_{n=0}^\\infty \\dfrac{(-1)^n x^{2n}}{(2n)!}\\)","solution":"This is the standard Maclaurin series for cosine."},{"type":"regular","q":"Find the radius of convergence for \\(\\sum_{n=1}^\\infty \\dfrac{x^n}{n \\cdot 2^n}\\).","answer":"2","solution":"By the ratio test, \\(\\lim_{n \\to \\infty}\\left|\\dfrac{x}{2} \\cdot \\dfrac{n}{n+1}\\right| = \\dfrac{|x|}{2}\\), so \\(R = 2\\)."},{"type":"regular","q":"Approximate \\(\\ln(1.2)\\) using the first three terms of the Maclaurin series for \\(\\ln(1+x)\\).","answer":"\\(\\approx 0.1827\\)","solution":"\\(\\ln(1.2) \\approx 0.2 - \\dfrac{0.04}{2} + \\dfrac{0.008}{3} \\approx 0.1827\\)."},{"type":"regular","q":"Does \\(\\sum_{n=1}^\\infty \\dfrac{(-1)^{n+1}}{\\sqrt{n}}\\) converge?","answer":"Yes","solution":"By the alternating series test, terms decrease to 0."},{"type":"regular","q":"What is the interval of convergence for \\(\\sum_{n=0}^\\infty \\dfrac{(x+2)^n}{3^n}\\)?","answer":"\\((-5, 1)\\)","solution":"Radius is 3, centered at \\(-2\\): \\(-2-3 < x < -2+3\\)."},{"type":"word","q":"A radioactive substance decays such that the amount remaining after \\(n\\) half-lives is \\(A_0 \\cdot \\left(\\dfrac{1}{2}\\right)^n\\). What fraction of the original amount remains after infinitely many half-lives?","answer":"0","solution":"\\(\\lim_{n \\to \\infty} A_0 \\cdot \\left(\\dfrac{1}{2}\\right)^n = 0\\)."},{"type":"word","q":"A series of discounts is applied to a product: 10% off, then 10% of the remaining price off, and so on. If the original price is \\$100, what is the limiting price?","answer":"\\$0","solution":"The price after \\(n\\) discounts is \\(100 \\cdot (0.9)^n \\to 0\\)."},{"type":"word","q":"A vibrating string has displacement \\(y(t) = 0.1 \\sin(\\omega t)\\) where \\(\\omega\\) is small. Using the first two terms of the Maclaurin series, approximate \\(y(t)\\).","answer":"\\(y(t) \\approx 0.1\\omega t\\)","solution":"\\(\\sin(\\omega t) \\approx \\omega t\\) for small \\(\\omega t\\)."},{"type":"word","q":"A bank offers an investment with returns modeled by \\(\\sum_{n=1}^\\infty \\dfrac{1}{2^n}\\) times the initial investment. What is the total return?","answer":"1 times the initial investment","solution":"The sum of the geometric series \\(\\sum_{n=1}^\\infty \\dfrac{1}{2^n} = 1\\)."},{"type":"word","q":"A researcher studies a sequence of measurements \\(m_n = \\dfrac{100}{n^2}\\). Does the sequence converge, and to what value?","answer":"Yes, to 0","solution":"\\(\\lim_{n \\to \\infty}\\dfrac{100}{n^2} = 0\\)."},{"type":"word","q":"An algorithm produces approximations \\(a_n = 1 - \\dfrac{1}{n}\\). What value does the sequence approach?","answer":"1","solution":"\\(\\lim_{n \\to \\infty}\\left(1 - \\dfrac{1}{n}\\right) = 1\\)."},{"type":"word","q":"A series of payments is \\(\\sum_{n=1}^\\infty \\dfrac{500}{1.08^n}\\) dollars. Does this converge, and if so, to approximately what value?","answer":"Yes, approximately \\$6250","solution":"Geometric series: \\(\\dfrac{500/1.08}{1-1/1.08} \\approx 6250\\)."},{"type":"word","q":"A power series \\(\\sum_{n=0}^\\infty c_n x^n\\) has radius of convergence 5. For what values of \\(x\\) does the series definitely converge?","answer":"\\(|x| < 5\\)","solution":"A power series converges for all \\(x\\) with absolute value strictly less than the radius."},{"type":"word","q":"An engineer uses the Taylor expansion of \\(e^x\\) to approximate \\(e^{0.01}\\) with three terms. What is the approximation?","answer":"\\(\\approx 1.01005\\)","solution":"\\(e^{0.01} \\approx 1 + 0.01 + \\dfrac{(0.01)^2}{2} \\approx 1.01005\\)."},{"type":"word","q":"A series \\(\\sum_{n=1}^\\infty \\dfrac{\\sin(n)}{n^2}\\) is given. Does it converge?","answer":"Yes","solution":"Since \\(|\\sin(n)| \\leq 1\\) and \\(\\sum \\dfrac{1}{n^2}\\) converges, by comparison the series converges."},{"type":"word","q":"A population model uses \\(P_n = 1000 \\cdot \\left(\\dfrac{3}{4}\\right)^n\\). What is the long-term population?","answer":"0","solution":"\\(\\lim_{n \\to \\infty} 1000 \\cdot \\left(\\dfrac{3}{4}\\right)^n = 0\\)."},{"type":"word","q":"A series of energy releases is \\(\\sum_{n=1}^\\infty \\dfrac{1}{3^n}\\) joules. What is the total energy?","answer":"\\(\\dfrac{1}{2}\\) joule","solution":"Geometric series: \\(\\sum_{n=1}^\\infty \\dfrac{1}{3^n} = \\dfrac{1/3}{1-1/3} = \\dfrac{1}{2}\\)."},{"type":"word","q":"A Taylor series centered at \\(x = 2\\) for \\(f(x) = \\dfrac{1}{x}\\) is \\(\\sum_{n=0}^\\infty (-1)^n \\dfrac{(x-2)^n}{2^{n+1}}\\). What is the radius of convergence?","answer":"2","solution":"By the ratio test on the coefficients, \\(R = 2\\)."}]);
  add("calculus", "c9", 0, [{"type":"regular","q":"What is the order of the differential equation \\(y''' - 2y'' + y = 0\\)?","answer":"3","solution":"The order is the highest derivative present; here it is the third derivative."},{"type":"regular","q":"Is \\(y' + y^2 = \\sin x\\) linear or nonlinear?","answer":"Nonlinear","solution":"The \\(y^2\\) term makes it nonlinear; linear DEs have the dependent variable and its derivatives to the first power only."},{"type":"regular","q":"Solve \\(y' = 5\\).","answer":"\\(y = 5x + C\\)","solution":"Integrate both sides with respect to \\(x\\) to get \\(y = 5x + C\\)."},{"type":"regular","q":"Solve \\(y' = 3y\\).","answer":"\\(y = Ce^{3x}\\)","solution":"This is a separable exponential growth equation; separate variables and integrate to obtain \\(y = Ce^{3x}\\)."},{"type":"regular","q":"What is the order of \\(\\frac{d^4y}{dx^4} + x\\frac{d^2y}{dx^2} = 0\\)?","answer":"4","solution":"The highest derivative is the fourth derivative, so the order is 4."},{"type":"regular","q":"Solve \\(y' = -y\\), \\(y(0) = 3\\).","answer":"\\(y = 3e^{-x}\\)","solution":"The general solution is \\(y = Ce^{-x}\\); use the initial condition \\(y(0) = 3\\) to find \\(C = 3\\)."},{"type":"regular","q":"Is \\(y' + 2xy = e^{-x^2}\\) linear or nonlinear?","answer":"Linear","solution":"Both \\(y\\) and \\(y'\\) appear to the first power, so it is linear."},{"type":"regular","q":"Solve \\(y' = 0\\).","answer":"\\(y = C\\)","solution":"Integrating zero gives a constant function."},{"type":"regular","q":"What is the order of \\(y'' = -y\\)?","answer":"2","solution":"The highest derivative present is the second derivative."},{"type":"word","q":"A bacterial culture has a growth rate proportional to the population. Write the differential equation if the proportionality constant is \\(r\\).","answer":"\\(\\frac{dP}{dt} = rP\\)","solution":"Growth proportional to population means the rate of change equals a constant times the population."},{"type":"word","q":"A substance decays at a rate proportional to the amount present. If \\(y(t)\\) is the amount at time \\(t\\) and the constant is \\(k > 0\\), write the DE.","answer":"\\(\\frac{dy}{dt} = -ky\\)","solution":"Decay proportional to amount present is modeled with a negative proportionality constant."},{"type":"word","q":"The rate of cooling of an object is proportional to the difference between its temperature and the ambient temperature. Write the DE if \\(T\\) is object temperature, \\(T_a\\) is ambient, and \\(k > 0\\).","answer":"\\(\\frac{dT}{dt} = -k(T - T_a)\\)","solution":"Newton's law of cooling states the cooling rate is proportional to the temperature difference."},{"type":"word","q":"A bank account earns interest at a rate proportional to the balance. If \\(B(t)\\) is the balance and the interest rate is \\(r\\), what DE models this?","answer":"\\(\\frac{dB}{dt} = rB\\)","solution":"Interest earned is proportional to the current balance, giving exponential growth."},{"type":"word","q":"A drug is administered to a patient and metabolized at a rate proportional to the amount in the bloodstream. Write the DE if \\(A(t)\\) is the amount and \\(k > 0\\) is the metabolism constant.","answer":"\\(\\frac{dA}{dt} = -kA\\)","solution":"Metabolism at a rate proportional to amount present is exponential decay."},{"type":"word","q":"A rumor spreads through a population of size \\(N\\) at a rate proportional to the product of those who know and those who don't. If \\(y(t)\\) is the number who know, write the DE.","answer":"\\(\\frac{dy}{dt} = ky(N - y)\\)","solution":"Spread is proportional to the product of informed and uninformed populations, giving a logistic-type equation."}]);
  add("calculus", "c9", 1, [{"type":"regular","q":"Solve \\(\\frac{dy}{dx} = 2xy\\).","answer":"\\(y = Ce^{x^2}\\)","solution":"Separate variables to get \\(\\frac{dy}{y} = 2x\\,dx\\), then integrate both sides."},{"type":"regular","q":"Solve \\(\\frac{dy}{dx} = \\frac{y}{x}\\).","answer":"\\(y = Cx\\)","solution":"Separate to get \\(\\frac{dy}{y} = \\frac{dx}{x}\\), integrate to obtain \\(\\ln|y| = \\ln|x| + C\\)."},{"type":"regular","q":"Solve \\(y' = 4y\\), \\(y(0) = 1\\).","answer":"\\(y = e^{4x}\\)","solution":"General solution is \\(y = Ce^{4x}\\); use \\(y(0) = 1\\) to get \\(C = 1\\)."},{"type":"regular","q":"Solve \\(\\frac{dy}{dx} = \\frac{2x}{y}\\).","answer":"\\(y^2 = 2x^2 + C\\)","solution":"Separate to get \\(y\\,dy = 2x\\,dx\\), integrate both sides."},{"type":"regular","q":"Solve \\(y' = \\frac{x^2}{y^2}\\).","answer":"\\(y^3 = x^3 + C\\)","solution":"Separate to get \\(y^2\\,dy = x^2\\,dx\\), integrate to obtain \\(\\frac{y^3}{3} = \\frac{x^3}{3} + C\\)."},{"type":"regular","q":"Solve \\(\\frac{dy}{dx} = e^{x+y}\\).","answer":"\\(y = -\\ln(C - e^x)\\)","solution":"Rewrite as \\(e^{-y}\\,dy = e^x\\,dx\\), integrate both sides."},{"type":"regular","q":"Solve \\(y' = 6y\\), \\(y(0) = 2\\).","answer":"\\(y = 2e^{6x}\\)","solution":"Separate variables and integrate; use initial condition to find \\(C = 2\\)."},{"type":"regular","q":"Solve \\(\\frac{dy}{dx} = \\frac{1}{xy}\\).","answer":"\\(y^2 = 2\\ln|x| + C\\)","solution":"Separate to get \\(y\\,dy = \\frac{dx}{x}\\), integrate both sides."},{"type":"regular","q":"Solve \\(y' = -2y\\), \\(y(0) = 5\\).","answer":"\\(y = 5e^{-2x}\\)","solution":"General solution is \\(y = Ce^{-2x}\\); apply \\(y(0) = 5\\) to get \\(C = 5\\)."},{"type":"word","q":"A tank contains 100 gallons of pure water. Saltwater with concentration 2 lb/gal flows in at 5 gal/min and the mixture flows out at 5 gal/min. Write the DE for the amount of salt \\(S(t)\\).","answer":"\\(\\frac{dS}{dt} = 10 - \\frac{S}{20}\\)","solution":"Salt in at \\(5 \\times 2 = 10\\) lb/min; salt out at \\(5 \\times \\frac{S}{100} = \\frac{S}{20}\\) lb/min."},{"type":"word","q":"A falling object experiences air resistance proportional to velocity. If \\(v(t)\\) is velocity and \\(g\\) is gravitational acceleration, write the DE with drag constant \\(k\\).","answer":"\\(\\frac{dv}{dt} = g - kv\\)","solution":"Gravitational force minus drag force gives the net acceleration."},{"type":"word","q":"A chemical reaction converts substance A into substance B at a rate proportional to the amount of A. If \\(y(t)\\) is the amount of B formed and \\(y_0\\) is the initial amount of A, write the DE.","answer":"\\(\\frac{dy}{dt} = k(y_0 - y)\\)","solution":"The reaction rate is proportional to the remaining amount of A, which is \\(y_0 - y\\)."},{"type":"word","q":"A population of fish in a lake grows at a rate proportional to the current population and inversely proportional to the available food (constant \\(F\\)). Write the DE.","answer":"\\(\\frac{dP}{dt} = k\\frac{P}{F}\\) or \\(\\frac{dP}{dt} = \\frac{kP}{F}\\)","solution":"Growth rate is proportional to population and inversely proportional to food availability."},{"type":"word","q":"A heater warms a room from 60°F to 75°F. The heating rate is proportional to the difference between desired and current temperature. Write the DE for room temperature \\(T(t)\\).","answer":"\\(\\frac{dT}{dt} = k(75 - T)\\)","solution":"Heating rate is proportional to the temperature difference between target and current."},{"type":"word","q":"An investor's wealth grows at a rate proportional to current wealth minus fixed expenses \\(E\\). Write the DE for wealth \\(W(t)\\).","answer":"\\(\\frac{dW}{dt} = r(W - E)\\)","solution":"Growth applies to wealth above the expense level, giving a rate proportional to \\(W - E\\)."}]);
  add("calculus", "c9", 2, [{"type":"regular","q":"A radioactive isotope decays with half-life 5 years. Find the decay constant \\(k\\) in \\(y = y_0 e^{-kt}\\).","answer":"\\(k = \\frac{\\ln 2}{5} \\approx 0.1386\\)","solution":"Half-life formula: \\(t_{1/2} = \\frac{\\ln 2}{k}\\), so \\(5 = \\frac{\\ln 2}{k}\\)."},{"type":"regular","q":"A substance has decay constant \\(k = 0.05\\) per year. What is its half-life?","answer":"\\(t_{1/2} = \\frac{\\ln 2}{0.05} \\approx 13.86\\) years","solution":"Use \\(t_{1/2} = \\frac{\\ln 2}{k}\\) with \\(k = 0.05\\)."},{"type":"regular","q":"Solve the logistic equation \\(P' = 2P(1 - P/100)\\) with \\(P(0) = 10\\).","answer":"\\(P(t) = \\frac{100}{1 + 9e^{-2t}}\\)","solution":"Use separation of variables on the logistic equation with carrying capacity \\(K = 100\\) and rate \\(r = 2\\)."},{"type":"regular","q":"A cup of coffee at 95°C is placed in a room at 20°C. The cooling constant is \\(k = 0.1\\) per minute. Find the temperature after 5 minutes.","answer":"\\(T(5) = 20 + 75e^{-0.5} \\approx 65.5°C\\)","solution":"Use Newton's law of cooling: \\(T(t) = T_a + (T_0 - T_a)e^{-kt} = 20 + 75e^{-0.5}\\)."},{"type":"regular","q":"A population follows \\(P' = 0.3P(1 - P/500)\\). What is the carrying capacity?","answer":"500","solution":"In the logistic equation \\(P' = rP(1 - P/K)\\), the carrying capacity is \\(K\\)."},{"type":"regular","q":"A radioactive sample has 80 grams initially. After 10 years, 20 grams remain. Find the decay constant \\(k\\).","answer":"\\(k = \\frac{\\ln 4}{10} \\approx 0.1386\\)","solution":"From \\(20 = 80e^{-10k}\\), we get \\(e^{-10k} = 0.25\\), so \\(k = \\frac{\\ln 4}{10}\\)."},{"type":"regular","q":"A substance decays with \\(y' = -0.02y\\). What fraction remains after 50 years?","answer":"\\(e^{-1} \\approx 0.368\\) or about 36.8%","solution":"After 50 years, \\(y(50) = y_0 e^{-0.02 \\times 50} = y_0 e^{-1}\\)."},{"type":"regular","q":"Newton's law of cooling for an object cooling from 100°C to room temperature 25°C with constant \\(k = 0.05\\) gives what solution form?","answer":"\\(T(t) = 25 + 75e^{-0.05t}\\)","solution":"Use \\(T(t) = T_a + (T_0 - T_a)e^{-kt}\\) with \\(T_a = 25\\), \\(T_0 = 100\\), \\(k = 0.05\\)."},{"type":"regular","q":"A population of bacteria grows logistically with \\(P' = 0.5P(1 - P/1000)\\) and \\(P(0) = 100\\). What is the equilibrium population?","answer":"1000","solution":"The equilibrium is the carrying capacity \\(K = 1000\\), where \\(P' = 0\\)."},{"type":"word","q":"A radioactive element has a half-life of 8 days. If you start with 200 mg, how much remains after 24 days?","answer":"25 mg","solution":"After 24 days = 3 half-lives, the amount is \\(200 \\times (1/2)^3 = 25\\) mg."},{"type":"word","q":"A patient is given a drug that decays in the body with constant \\(k = 0.15\\) per hour. If 500 mg is administered, how much remains after 4 hours?","answer":"\\(500e^{-0.6} \\approx 272\\) mg","solution":"Use exponential decay: \\(y(4) = 500e^{-0.15 \\times 4} = 500e^{-0.6}\\)."},{"type":"word","q":"A lake initially contains 1000 fish. The population grows logistically with growth rate 0.1 per year and carrying capacity 5000. Approximately how many fish are there after 10 years?","answer":"Approximately 3000 fish (exact value depends on solution method)","solution":"Solve \\(P' = 0.1P(1 - P/5000)\\) with \\(P(0) = 1000\\) to find \\(P(10)\\)."},{"type":"word","q":"A hot pizza at 180°C is left in a room at 22°C. After 10 minutes, it cools to 100°C. Find the cooling constant \\(k\\).","answer":"\\(k = \\frac{1}{10}\\ln\\left(\\frac{158}{78}\\right) \\approx 0.0701\\)","solution":"Use \\(100 = 22 + 158e^{-10k}\\) to solve for \\(k\\)."},{"type":"word","q":"A savings account with initial balance \\$1000 earns interest at a rate proportional to the balance with constant 0.05 per year. What is the balance after 20 years?","answer":"\\(1000e^{1} \\approx \\$2718.28\\)","solution":"Exponential growth: \\(B(20) = 1000e^{0.05 \\times 20} = 1000e^1\\)."},{"type":"word","q":"A viral infection spreads logistically through a population of 10,000 with growth rate 0.2 per day. If 50 people are infected initially, approximately how many are infected after 20 days?","answer":"Approximately 9500 people (population approaches carrying capacity)","solution":"Solve \\(I' = 0.2I(1 - I/10000)\\) with \\(I(0) = 50\\) to find \\(I(20)\\)."}]);
  addCum("calculus", "c9", [{"type":"regular","q":"What is the order of \\(y^{(5)} + xy'' = \\sin x\\)?","answer":"5","solution":"The highest derivative present is the fifth derivative."},{"type":"regular","q":"Solve \\(y' = 7\\).","answer":"\\(y = 7x + C\\)","solution":"Integrate both sides with respect to \\(x\\)."},{"type":"regular","q":"Solve \\(y' = -5y\\).","answer":"\\(y = Ce^{-5x}\\)","solution":"This is a separable exponential decay equation."},{"type":"regular","q":"Solve \\(\\frac{dy}{dx} = \\frac{3x}{y}\\).","answer":"\\(y^2 = 3x^2 + C\\)","solution":"Separate variables to get \\(y\\,dy = 3x\\,dx\\), then integrate."},{"type":"regular","q":"Solve \\(y' = 2y\\), \\(y(0) = 4\\).","answer":"\\(y = 4e^{2x}\\)","solution":"General solution is \\(y = Ce^{2x}\\); use initial condition to find \\(C = 4\\)."},{"type":"regular","q":"Is \\(y'' + 3y' - y = e^x\\) linear or nonlinear?","answer":"Linear","solution":"All terms involving \\(y\\) and its derivatives are to the first power."},{"type":"regular","q":"A radioactive substance has half-life 15 years. Find \\(k\\) in \\(y = y_0 e^{-kt}\\).","answer":"\\(k = \\frac{\\ln 2}{15} \\approx 0.0462\\)","solution":"Use the half-life formula \\(t_{1/2} = \\frac{\\ln 2}{k}\\)."},{"type":"regular","q":"Solve \\(y' = \\frac{4}{x}\\), \\(y(1) = 2\\).","answer":"\\(y = 4\\ln|x| + 2\\)","solution":"Integrate to get \\(y = 4\\ln|x| + C\\); use \\(y(1) = 2\\) to find \\(C = 2\\)."},{"type":"regular","q":"What is the order of \\(\\frac{d^2y}{dx^2} + 5\\frac{dy}{dx} + 6y = 0\\)?","answer":"2","solution":"The highest derivative is the second derivative."},{"type":"regular","q":"Solve \\(y' = -3y\\), \\(y(0) = 7\\).","answer":"\\(y = 7e^{-3x}\\)","solution":"General solution is \\(y = Ce^{-3x}\\); use \\(y(0) = 7\\) to get \\(C = 7\\)."},{"type":"regular","q":"A population follows \\(P' = 0.4P(1 - P/800)\\). What is the carrying capacity?","answer":"800","solution":"In the logistic equation \\(P' = rP(1 - P/K)\\), the carrying capacity is \\(K\\)."},{"type":"regular","q":"Solve \\(\\frac{dy}{dx} = e^{x-y}\\).","answer":"\\(y = \\ln(e^x + C)\\)","solution":"Rewrite as \\(e^y\\,dy = e^x\\,dx\\), integrate both sides."},{"type":"word","q":"A tank contains 50 gallons of water with 10 pounds of salt. Fresh water flows in at 2 gal/min and the mixture flows out at 2 gal/min. Write the DE for salt amount \\(S(t)\\).","answer":"\\(\\frac{dS}{dt} = -\\frac{S}{25}\\)","solution":"Salt out at \\(2 \\times \\frac{S}{50} = \\frac{S}{25}\\) lb/min; no salt in."},{"type":"word","q":"A loan of \\$50,000 is paid off with interest at rate 0.06 per year and fixed payments. Write the DE for loan balance \\(L(t)\\) if payments are made continuously at rate \\(p\\).","answer":"\\(\\frac{dL}{dt} = 0.06L - p\\)","solution":"Interest accrues at 0.06 times the balance; payments reduce the balance at rate \\(p\\)."},{"type":"word","q":"A forest fire spreads at a rate proportional to the number of burning trees \\(B(t)\\) and the number of unburned trees \\(T - B\\). Write the DE.","answer":"\\(\\frac{dB}{dt} = kB(T - B)\\)","solution":"Spread requires both burning and unburned trees; the rate is proportional to their product."},{"type":"word","q":"An object falls from rest with air resistance proportional to velocity. If \\(v(t)\\) is velocity, \\(g = 10\\) m/s², and drag constant is \\(k = 0.5\\), write the DE.","answer":"\\(\\frac{dv}{dt} = 10 - 0.5v\\)","solution":"Net force is gravity minus drag force, giving acceleration as \\(g - kv\\)."},{"type":"word","q":"A radioactive element decays with half-life 12 days. If 300 grams are present initially, how much remains after 36 days?","answer":"37.5 grams","solution":"After 36 days = 3 half-lives, the amount is \\(300 \\times (1/2)^3 = 37.5\\) grams."},{"type":"word","q":"A cup of tea cools from 90°C to 60°C in 10 minutes in a room at 20°C. Find the cooling constant \\(k\\).","answer":"\\(k = \\frac{1}{10}\\ln\\left(\\frac{70}{40}\\right) = \\frac{1}{10}\\ln(1.75) \\approx 0.0560\\)","solution":"Use Newton's law: \\(60 = 20 + 70e^{-10k}\\) to solve for \\(k\\)."},{"type":"word","q":"A medication in the bloodstream decays with constant \\(k = 0.2\\) per hour. If 250 mg is injected, when does the amount drop below 50 mg?","answer":"After approximately 8 hours","solution":"Solve \\(50 = 250e^{-0.2t}\\) to get \\(t = \\frac{\\ln 5}{0.2} \\approx 8.05\\) hours."},{"type":"word","q":"A population of bacteria grows logistically with \\(P' = 0.3P(1 - P/2000)\\) and \\(P(0) = 200\\). What is the maximum population?","answer":"2000","solution":"The maximum is the carrying capacity \\(K\\), where growth stops."},{"type":"word","q":"An investment grows with compound interest at rate 0.08 per year. Starting with \\$5000, how much is there after 15 years?","answer":"\\(5000e^{1.2} \\approx \\$16,600\\)","solution":"Exponential growth: \\(A(15) = 5000e^{0.08 \\times 15} = 5000e^{1.2}\\)."},{"type":"word","q":"A disease spreads through a population of 50,000 with logistic growth rate 0.15 per day and initial infections 100. Approximately how many are infected after 30 days?","answer":"Approximately 49,900 (nearly the entire population)","solution":"Solve \\(I' = 0.15I(1 - I/50000)\\) with \\(I(0) = 100\\) to find \\(I(30)\\)."}]);
